INSERT INTO hunter_markdown_expected_r221 VALUES (
    '{"class_id":4,"collections":{"home.tbclasse":[{"armaduras":"Armaduras Leves, Médias e Escudos","armas":"Armas Simples, Marciais e Armas de Fogo","atributo_principal":"Força ou Destreza e Inteligência ou Sabedoria.","dado_vida":"1d10 por nível de Caçador","equipamento":"A: Armadura de Couro Batido, uma Cimitarra, uma Espada Curta, um Arco Longo, 20 Flechas, uma Aljava, um Foco Druídico (ramo de visco), um Pacote de Explorador e 7 PO.\r\n\r\nB: 150 PO.","ferramentas":"Escolha uma dentre Suprimentos de Alquimista, Kit de Disfarce, Ferramentas de Ferreiro, Kit de Herborismo e Kit de Envenenador","id_classe":4,"multiclass_armaduras":"Armaduras Leves","multiclass_armas":"Armas Marciais","multiclass_ferramentas":"Nenhuma","multiclass_pericias":"Escolha 1 entre Adestrar Animais, Atletismo, Furtividade, Intuição, Investigação, Natureza, Percepção e Sobrevivência","multiclass_requisitos":"Destreza 13 e Sabedoria 13","nome":"Caçador","pericias":"Escolha 3 entre Adestrar Animais, Atletismo, Intuição, Investigação, Natureza, Percepção, Furtividade e Sobrevivência","pv_nivel_1":"10 + modificador de Constituição","pv_por_nivel":"6 (metade do 1d10 + 1) + seu modificador de Constituição","resistencias":"Inteligência e Sabedoria.","slug":"cacador","tagline":"Rastreia o sobrenatural e o anota em seu diário — a mesma criatura não escapa duas vezes do mesmo jeito.","tags_json":["hit_dice:1d10","saves_prof{int, wis}","skills_lvl1{pick:3 de [adestrar-animais, atletismo, intuicao, investigacao, natureza, percepcao, furtividade, sobrevivencia]}","subclass_choices{3, 6, 10, 14, 18}","asi_choices{4, 8, 12, 16, 19}","multiclass_prof{armadura_leve, armas_marciais, pick:pericia:1}","prof{armadura_leve, armadura_media, escudos, armas_simples, armas_marciais, armas_fogo}","prof{pick:ferramenta:1}","multiclass_req{dex>=13, wis>=13}","starting_equipment{item{slug:studded-leather-armor, qty:1}, item{slug:arma-cimitarra, qty:1}, item{slug:arma-espada-curta, qty:1}, item{slug:arma-arco-longo, qty:1}, item{slug:arrows-20, qty:1}, item{slug:quiver, qty:1}, item{slug:sprig-of-mistletoe, qty:1}, item{slug:explorer-s-pack, qty:1}, currency{po:7}, alternative{currency{po:150}}}"]}],"home.tbclassehabilidade":[{"descricao":"*Marcar um alvo não é apontar pra ele; é decidir, em silêncio, que ele já perdeu. Anoto no diário o rosto, o cheiro e o jeito de pisar, porque a partir daí cada rastro que a criatura deixa vira uma página escrita com o meu nome guardado no fim.*\n\nVocê sempre tem a magia *Marca do Caçador [Hunter''s Mark]* preparada, e ela não conta contra seu total de magias preparadas. Como Caçador, você manifesta uma versão otimizada da magia diretamente como traço de classe.\n\n#### Marcar o Alvo (Conjuração Otimizada)\n\nComo uma **Ação Bônus**, você conjura *Marca do Caçador [Hunter''s Mark]* sem gastar espaço de magia e sem exigir Concentração, marcando uma criatura que possa ver a até **27 metros [90 pés]** como sua Presa Marcada. Ainda que não exija Concentração, a Marca dura o mesmo tempo que a magia duraria sob Concentração, encerrando-se também se a criatura morrer, se você aplicar a Marca em outra criatura ou se você ficar **Incapacitado** por mais de 1 minuto.\n\n#### Dado de Caçador\n\nSeus ataques com arma contra a Presa Marcada causam dano adicional do mesmo tipo da arma, igual a uma rolagem do seu Dado de Caçador, o dado escalonado da sua classe. Quando você conjura *Marca do Caçador [Hunter''s Mark]*, o dado base da magia é substituído pelo seu Dado de Caçador. O Dado de Caçador começa como **1d6** e cresce conforme você sobe de nível: torna-se **1d8** no 5º nível de Caçador, **1d10** no 11º nível e **1d12** no 17º nível.\n\n#### Apenas Uma Marca Ativa\n\nVocê só pode ter uma Marca do Caçador ativa por vez. Conjurar a magia novamente encerra a Marca anterior imediatamente, antes que a nova seja aplicada.\n\n#### Sentido da Presa\n\nEnquanto a sua Presa Marcada estiver no mesmo plano de existência que você, você conhece a direção geral dela e sente uma vibração leve sempre que ela é ferida.\n\n#### Efeito Mágico\n\nA Marca do Caçador é considerada um efeito mágico para fins de dissipar magia. Ela é tratada como conjurada de um espaço de magia de Círculo igual à metade do seu nível de Caçador, arredondada para baixo, até um máximo de 9º Círculo.","id_classe_id":4,"id_habilidade":880,"id_subclasse_id":null,"niveladquirido":1,"nome":"Marca do Caçador","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*O segredo da boa caça é a véspera; quem chega armado já chegou na metade. Passo a manhã afiando, reembalando e conferindo cada peça, porque no mato o erro que mata quase nunca é o do combate — é o da preguiça da noite anterior, que eu me recuso a cometer.*\n\nVocê passa cada manhã afiando, reembalando e conferindo seu equipamento. Seu corpo e suas armas estão sempre prontos para a próxima caçada.\n\n#### Estilo de Luta\n\nVocê aprende um Estilo de Luta da lista de Estilos de Luta do Caçador. Você não pode aprender o mesmo Estilo de Luta mais de uma vez, mesmo que outra habilidade lhe permita escolher um, e precisa cumprir os pré-requisitos do Estilo para aprendê-lo. Sempre que ganhar um nível de Caçador, você pode substituir este Estilo de Luta por outro disponível ao Caçador.\n\n#### Armas de Caçada\n\nVocê ganha o benefício de Maestria de Armas (Weapon Mastery) de três armas com as quais seja proficiente. Ao terminar um Descanso Longo, você pode trocar uma dessas Maestrias pela de outra arma.","id_classe_id":4,"id_habilidade":881,"id_subclasse_id":null,"niveladquirido":2,"nome":"Preparos de Caçada","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Não existe inimigo igual; cada um pede um tipo diferente de ódio. Estudei os hábitos de uns tantos até conhecê-los melhor do que a mim mesmo — como se movem, do que fogem, onde sangram — e anotei tudo com cuidado para nunca mais ser surpreendido por eles.*\n\nVocê escolheu uma categoria de criatura para estudar com obsessão. No 2º nível, escolha um tipo de criatura dentre Aberrações, Bestas, Celestiais, Constructos, Corruptores, Dragões, Elementais, Fadas, Gigantes, Humanoides, Monstruosidades ou Mortos-Vivos. Aquela categoria é o seu Inimigo Favorito. Você ganha um Inimigo Favorito adicional ao alcançar o 8º nível e novamente no 14º nível, totalizando três.\n\n#### Dano de Inimigo Favorito\n\nVocê adiciona o seu modificador de Inteligência ou Sabedoria, o que for sua habilidade de conjuração, com um mínimo de +1, ao dano dos seus ataques com arma contra criaturas do seu Inimigo Favorito. Esse bônus não escala com o nível, pois é a recompensa do seu estudo, não da sua força bruta.\n\n#### Rastreio Especializado\n\nVocê tem Vantagem em testes de Sabedoria (Sobrevivência) para rastrear criaturas do seu Inimigo Favorito e em testes de Inteligência (Arcanismo, História ou Natureza) para lembrar de informações sobre elas.\n\n#### Análise de Sinais\n\nCom 1 minuto de estudo sobre vestígios, carcaças ou trilhas de uma criatura do seu Inimigo Favorito, você determina automaticamente a espécie específica, os hábitos básicos, o terreno preferido e quaisquer resistências, imunidades ou vulnerabilidades amplamente conhecidas.","id_classe_id":4,"id_habilidade":884,"id_subclasse_id":null,"niveladquirido":2,"nome":"Inimigo Favorito","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Aprendi as palavras certas em segredo, deitado no escuro com um livro velho. Não é a magia dos salões nem a dos templos: é a que se colhe observando o mato, o sangue e o céu, e hoje uso ela como uso uma faca — pouco, mas sempre bem.*\n\nVocê aprende a moldar magias práticas para a caça, feitiços de exploração, controle e revelação. Você pode conjurar magias da Lista de Magias do Caçador.\n\n#### Espaços de Magia\n\nA Tabela do Caçador mostra quantos espaços de magia você tem para conjurar suas magias de 1º Círculo ou superior. Para conjurar uma dessas magias, você gasta um espaço de magia de Círculo igual ou superior ao da magia. Você recupera todos os espaços gastos ao terminar um Descanso Longo.\n\n#### Magias Preparadas\n\nVocê prepara a lista de magias de 1º Círculo ou superior que pode conjurar com esta característica. Para isso, escolha da Lista de Magias do Caçador um número de magias igual ao indicado na coluna Magias Preparadas da Tabela do Caçador. As magias escolhidas devem pertencer a um Círculo para o qual você tenha espaços de magia. Sempre que terminar um Descanso Longo, você pode substituir qualquer quantidade das magias preparadas por outras magias da Lista de Magias do Caçador.\n\n#### Habilidade de Conjuração\n\nAo alcançar o 1º nível, escolha Inteligência ou Sabedoria como sua habilidade de conjuração. Essa escolha define o foco do seu estudo, livros e investigação para Inteligência ou instinto e leitura do mundo para Sabedoria, e é permanente. Você usa esse atributo sempre que uma magia se referir à sua habilidade de conjuração, e o emprega ao determinar a CD dos seus testes de resistência de magia e o seu modificador de ataque mágico:\n\nCD de Resistência de Magia = 8 + bônus de proficiência + modificador de Inteligência ou Sabedoria\n\nModificador de Ataque Mágico = bônus de proficiência + modificador de Inteligência ou Sabedoria\n\n#### Conjuração Ritual\n\nVocê pode conjurar como ritual qualquer magia de Caçador que tenha a propriedade Ritual, desde que ela esteja entre as magias que você preparou.\n\n#### Foco de Conjuração\n\nVocê usa um foco druídico ou um diário de caça como foco de conjuração para suas magias de Caçador.","id_classe_id":4,"id_habilidade":1019,"id_subclasse_id":null,"niveladquirido":1,"nome":"Conjuração","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Não tem nada de mágico nos meus truques; são só truques que ninguém mais quis aprender. Guardo cada um neste caderno gasto, ao lado de fórmulas, armadilhas e sinais, e vou provando qual serve para qual presa até o método virar reflexo que a mão executa sozinha.*\n\nVocê adquire Segredos do Caçador, técnicas práticas, alquímicas ou esotéricas reunidas ao longo dos seus anos de aprendizado. Os Segredos estão organizados em três Linhas temáticas: **Alquimia e Poções**, com frascos, óleos, elixires e granadas que você prepara entre caçadas; **Armadilhas e Emboscadas**, com redes, ganchos, estrepes, minas e técnicas de controle de terreno; e **Conhecimentos Ancestrais (Sinais)**, com gestos, palavras e símbolos esotéricos que dobram a realidade contra a presa. A lista completa de Segredos está a seguir.\n\n#### Linha Mestra\n\nAo escolher sua Ordem no 3º nível, você define qual das três Linhas é a sua Linha Mestra. Você conhece todos os Segredos da sua Linha Mestra dentro dos Graus que já desbloqueou, e eles estão sempre disponíveis para uso, sem precisar de preparação.\n\n#### Graus de Segredos\n\nCada Linha tem quatro Graus internos de poder, que você desbloqueia à medida que sobe de nível. O 1º Grau está disponível no 2º nível, o 2º Grau no 5º nível, o 3º Grau no 9º nível e o 4º Grau no 13º nível.\n\n#### Segredos Preparados (Outras Linhas)\n\nAlém dos Segredos da sua Linha Mestra, sempre disponíveis, você pode preparar Segredos das outras duas Linhas ao terminar um Descanso Longo. O número de Segredos que você pode preparar de outras Linhas é igual ao seu Bônus de Proficiência. Você só pode preparar Segredos de Graus que já tenha desbloqueado.\n\n#### Pontos de Segredo\n\nVocê tem uma reserva de Pontos de Segredo igual ao seu nível de Caçador. Cada Segredo lista quantos pontos custam para ser usado. Quando um Segredo tiver um **Aprimoramento** e você optar por ativá-lo, o custo dele em Pontos de Segredo aumenta em **1**. Você recupera todos os Pontos de Segredo ao terminar um Descanso Longo.\n\n#### CD dos Segredos\n\nQuando um Segredo exigir um teste de resistência, a CD é a sua CD de Magia (8 + bônus de proficiência + modificador de Inteligência ou Sabedoria). Quando exigir uma rolagem de ataque, use o seu modificador de ataque mágico, exceto quando o Segredo substituir um ataque com arma, caso em que você usa a sua rolagem de ataque com arma.\n\nAs três Linhas e os seus Segredos estão descritos a seguir; cada Segredo indica o seu custo em **Pontos de Segredo**.","id_classe_id":4,"id_habilidade":1020,"id_subclasse_id":null,"niveladquirido":2,"nome":"Segredos do Caçador","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A sabedoria que carrego não enfeita conversa; ela me mantém vivo. Anotei cedo no diário que saber uma coisa a fundo vale mais do que saber cem pela metade, então escolhi um punhado de ofícios e afiei cada um até virarem segunda natureza, tão certos quanto respirar.*\n\nEscolha uma perícia baseada em Inteligência ou Sabedoria com a qual você seja proficiente. Seu bônus de proficiência é dobrado em qualquer teste de habilidade que você faça com aquela perícia. Você escolhe uma perícia adicional para este efeito ao alcançar o 9º nível.","id_classe_id":4,"id_habilidade":1021,"id_subclasse_id":null,"niveladquirido":3,"nome":"Instinto de Caçador","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*O pacto está selado. A forma física pode mudar, mas a lealdade é absoluta. Ele é sua sombra armada com presas e garras.*\n  Você invoca um Espírito Primordial da Natureza para lhe auxiliar.\n- **Estatísticas de Jogo:** O espírito usa o bloco de estatísticas **Espírito Primordial** (fornecido ao final desta subclasse). Ele assume a aparência de uma fera à sua escolha, adequada à forma totêmica selecionada.\n- **Forma Totêmica:** Ao invocar o espírito, escolha um dos ambientes: **Terra** (focado em defesa terrestre), **Céu** (focado em voo) ou **Marés** (focado em natação). Essa escolha determina o tipo de deslocamento do espírito conforme detalhado no bloco de estatísticas.\n- **Iniciativa e Turno:** O espírito compartilha sua contagem de Iniciativa, mas age imediatamente após o seu turno. A única ação que ele realiza sozinho é a ação **Esquivar**.\n- **Comando de Combate:** Você pode usar sua **Ação Bônus** para comandar o espírito a realizar a ação **Atacar**, **Disparada**, **Desengajar** ou **Ajuda**. Se você tiver a característica **Ataque Extra**, pode substituir um dos seus ataques da ação **Atacar** para comandar o espírito a atacar.\n- **Vida e Morte:** Se o espírito for reduzido a **0 Pontos de Vida**, ele se dissipa. Você pode trazê-lo de volta com todos os PV ao terminar um **Descanso Longo**. Alternativamente, você pode gastar **1 Ponto de Segredo** e **1 minuto** em ritual para invocá-lo magicamente em um espaço a até **1,5 metro [5 pés]** de você.","id_classe_id":4,"id_habilidade":1023,"id_subclasse_id":21,"niveladquirido":3,"nome":"Companheiro Primordial","nome_ingles":null,"table_only":false,"tags_json":["action=bonus_action","instant{grant:companion(target:active)}","while_active{action:bonus_action, instant{grant:companion_command{attack, dash, disengage, help}}}","requires:attack_action, attacks:-1{instant{grant:companion_command{attack}}}","trigger=long_rest, instant{heal:companion(full)}","action=free, resource_cost:pontos_de_segredo:1, instant{grant:companion(target:active, range:5ft)}"]},{"descricao":"*A natureza não é estática. Seu companheiro se adapta, desenvolvendo couro mais grosso, sentidos aguçados ou garras impregnadas com o poder das tempestades.*\n  Seu Espírito Primordial desenvolve adaptações sobrenaturais.\n- **Escolhas:** Você ganha **1 Característica Menor** (listadas abaixo) agora. Você ganha uma característica adicional no **6º**, **10º**, **14º** e **18º** níveis de Caçador.\n- **Progressão:** A partir do **6º nível**, sempre que ganhar uma nova característica, você pode escolher entre as **Características Menores** ou **Características Maiores**.\n- **Restrição:** Você não pode escolher a mesma característica mais de uma vez, a menos que a descrição diga o contrário.\n#### Características Menores\n- **Audição e Olfato Aguçados:** O espírito tem **Vantagem** em testes de **Sabedoria (Percepção)** que dependam de audição ou olfato.\n- **Camuflagem:** O espírito tem **Vantagem** em testes de **Destreza (Furtividade)** enquanto estiver em terreno natural ou sob condições de **Penumbra** e **Escuridão**.\n- **[Escalada Aracnídea](tbMagia, escalada-aracnidea):** O espírito ganha deslocamento de **Escalada** igual ao seu deslocamento de caminhada. Ele pode escalar superfícies difíceis, incluindo tetos, sem precisar fazer testes de Habilidade.\n- **Prender a Respiração:** O espírito pode prender a respiração por **1 hora**.\n- **Resistência Elemental:** Escolha um tipo de dano: **Ácido**, **Elétrico**, **Fogo**, **Frio** ou **Trovão**. O espírito ganha **Resistência** ao tipo escolhido. Você pode selecionar esta opção múltiplas vezes, escolhendo um tipo diferente a cada vez.\n- **Táticas de Matilha:** O espírito tem **Vantagem** nas jogadas de ataque contra uma criatura se você ou outro aliado do espírito estiver a até **1,5 metro [5 pés]** da criatura e não estiver **Incapacitado**.","id_classe_id":4,"id_habilidade":1024,"id_subclasse_id":21,"niveladquirido":3,"nome":"Evolução Totêmica","nome_ingles":null,"table_only":false,"tags_json":["pick:caracteristica_totemica:{classlvl=3:1, classlvl=6:1, classlvl=10:1, classlvl=14:1, classlvl=18:1}","define{caracteristica_totemica: list{ audicao_olfato:{adv:check{percepcao}}, camuflagem:{adv:check{furtividade}}, escalada_aracnidea:{move:climb, move:wall}, resistencia_elemental:{pick:resist:{acido | raio | fogo | frio | trovejante}}, taticas_de_matilha:{adv:attack{requires:ally(range:5ft)}} }}"]},{"descricao":"*\"Eu o vi hesitar quando o selo brilhou. Não foi muito — um meio passo, um olho que apertou. Mas bastou. Significa que ele tem algo a perder. E se tem algo a perder, pode ser abatido.\"*\n  Você analisa a fisiologia e a natureza sobrenatural da sua presa no momento em que foca sua atenção nela.\n- **Leitura de Fraquezas:** Imediatamente após você aplicar sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)** em uma criatura, você descobre se ela possui quaisquer **Imunidades a Dano**, **Resistências a Dano** ou **Vulnerabilidades a Dano**. O Mestre também deve revelar se a criatura possui **Imunidades a Condição**.\n- **Olhar Treinado:** Enquanto uma criatura estiver sob efeito da sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)**, você tem **Vantagem** em testes de **Inteligência (Arcanismo)**, **Inteligência (História)**, **Inteligência (Natureza)** ou **Inteligência (Religião)** realizados para recordar informações sobre a origem, hábitos ou poderes dela.\n- **Limitação:** Esta característica revela apenas traços estatísticos e fisiológicos da criatura. Ela não revela informações de trama, como identidades secretas, nomes verdadeiros ou planos ocultos.","id_classe_id":4,"id_habilidade":1025,"id_subclasse_id":118,"niveladquirido":3,"nome":"Estudo do Inimigo","nome_ingles":null,"table_only":false,"tags_json":["trigger=ability{marca_do_cacador, classe:cacador}, instant{detect:{imunidades, resistencias, vulnerabilidades, imunidades_condicao}(target)}","while_active{requires:target{mark:ability{marca_do_cacador, classe:cacador}}, adv:check{arcanismo}, adv:check{historia}, adv:check{natureza}, adv:check{religiao}}"]},{"descricao":"*\"Não preciso vê-lo para saber que está ali. Rastro de sangue seco, pegadas repetidas... a criatura acha que está escondida, mas cada descuido escreve o nome que eu preciso.\"*\n  Você aprende a realizar um ritual de investigação para conectar-se magicamente a uma presa antes mesmo de encontrá-la.\n- **Ritual de Investigação:** Você deve gastar **10 minutos** analisando um local em busca de pistas de uma criatura específica. Ao final deste tempo, se você tiver reunido ao menos **3 Pistas Válidas** (veja abaixo) e souber o Tipo de Criatura do alvo, você pode usar uma **Ação Bônus** para aplicar sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)** nela.\n- **Sem Linha de Visão:** Ao usar esta característica, você não precisa ver a criatura e ela não precisa estar no seu alcance normal, desde que esteja a até **8 quilômetros [5 milhas]** de você e no mesmo Plano de Existência.\n- **Pistas Válidas:** Para o ritual funcionar, o Mestre deve confirmar que você identificou 3 elementos distintos, como: **Vestígios Físicos** (pegadas, sangue), **Testemunhos Confiáveis** (descrições de sobreviventes), **Vestígios Arcanos** (resíduos mágicos), **Padrões de Comportamento** (horários, rotas) ou **Registros Prévios** (anotações em diários ou lendas locais).\n- **Custo e Falha:** Esta habilidade consome o uso da sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)** normalmente. Se a criatura estiver fora do alcance ou em outro plano, o uso é gasto sem efeito e você sente que o rastro \"esfriou\".\n- **Duração:** A marca dura conforme as regras normais da habilidade, até que você marque outro alvo ou descanse.","id_classe_id":4,"id_habilidade":1026,"id_subclasse_id":118,"niveladquirido":3,"nome":"Marca Antecipada","nome_ingles":null,"table_only":false,"tags_json":["action=bonus_action","instant{ apply:ability{marca_do_cacador, classe:cacador}(target:creature(range:26400ft, without{los}), requires:same_plane) }","resource_cost:ability{marca_do_cacador, classe:cacador}"]},{"descricao":"*\"Não aprendi a correr mais rápido. Aprendi a começar do outro lado. Um símbolo na parede, outro na lâmina — quando o monstro percebe, eu já não estou onde deveria.\"*\n  Você aprende a manipular o espaço no campo de batalha gravando âncoras mágicas.\n- **Criar uma Runa:** No seu turno, você pode usar uma **Ação Bônus** para criar magicamente uma Runa de Travessia em um espaço ou objeto que você possa ver a até **9 metros [30 pés]** de você. A runa é visível apenas para você.\n- **Limite de Runas:** Você pode ter até **2 Runas de Travessia** ativas simultaneamente. Se você criar uma terceira runa, a mais antiga desaparece imediatamente.\n- **Passo Rúnico (Ataque):** Sempre que você realizar a ação **Atacar** no seu turno, imediatamente antes de realizar a jogada de ataque, você pode se teletransportar para um espaço desocupado a até **3 metros [10 pés]** de uma de suas Runas de Travessia que você possa ver. Esse teleporte não provoca **Ataques de Oportunidade**.\n- **Salto Direto:** Como uma **Ação Bônus**, você pode se teletransportar para um espaço desocupado a até **3 metros [10 pés]** de uma de suas Runas de Travessia que você possa ver.\n- **Marca na Arma (Arremesso Cintilante):** Quando você realizar um ataque com uma arma que esteja empunhando, você pode infundir a arma com uma runa temporária. Se o ataque envolver lançar a arma ou disparar uma munição (fazendo-a sair da sua mão), após o ataque ser resolvido, você pode se teletransportar magicamente para um espaço desocupado a até **3 metros [10 pés]** do local onde a arma ou munição parou. Isso faz parte da ação do ataque e não requer ação adicional.","id_classe_id":4,"id_habilidade":1027,"id_subclasse_id":115,"niveladquirido":3,"nome":"Runas de Travessia","nome_ingles":null,"table_only":false,"tags_json":["action=bonus_action","instant{ mark{runa_travessia, target:point(range:30ft), max:2} }","trigger=action{attack}, instant{teleport:10ft(from:mark{runa_travessia}, without{aoo})}","action=bonus_action, instant{teleport:10ft(from:mark{runa_travessia})}","trigger=hit_thrown, instant{teleport:10ft(from:wielded, without{aoo})}"]},{"descricao":"*\"O ar muda antes do portal abrir. O cheiro fica mais fino, o som parece bater numa parede que não está ali. Eu aprendi a ouvir esse silêncio.\"*\n  Você desenvolve um sexto sentido para detectar intrusões na realidade.\n- **Detectar Portais:** Como uma **Ação**, você expande seus sentidos para detectar a presença de portais planares. Você descobre a localização e a distância de qualquer portal ativo ou fenda planar em um raio de **1,5 quilômetro [1 milha]** de você.\n- **Rastro de Presa:** Se uma criatura do tipo escolhido na sua característica **Presa Estudada** tiver atravessado um portal detectado recentemente, você sente uma conexão intuitiva indicando que a presa está associada àquele portal específico, embora não saiba a localização exata dela no outro plano.\n- **Usos:** Você pode usar esta característica um número de vezes igual ao seu modificador de **Sabedoria** ou **Inteligência** (mínimo de 1). Você recupera todos os usos gastos ao terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1028,"id_subclasse_id":115,"niveladquirido":3,"nome":"Sentinela Planar","nome_ingles":null,"table_only":false,"tags_json":["action=action","instant{ detect:portal(range:5280ft) }","uses{max(1, spell_mod), reset:long_rest}"]},{"descricao":"*\"Eles dormem em dobras de roupa, sob a pele, entre trançados de couro. Não como parasitas — como guarda-costas. Quando dou o sinal, o chão mexe e o ar escurece.\"*\n  Você abriga um enxame de espíritos da natureza ou pequenas criaturas (insetos, roedores, aves) que auxiliam você em combate.\n- **Natureza do Enxame:** O enxame habita seu espaço e se move com você. Ele é intangível para os outros até que você o comande. As criaturas são consideradas Minúsculas.\n- **Gatilho:** Uma vez em cada um dos seus turnos, quando você acertar uma criatura com uma jogada de ataque, você pode fazer com que o enxame auxilie o golpe. Ao fazer isso, escolha um dos efeitos abaixo para ocorrer imediatamente após o ataque.\n  - **Opção 1 - Assalto Rastejante:** O ataque causa dano extra ao alvo igual a **1 Dado de Caçador**. O tipo de dano é **Perfurante** ou **Necrótico** (à sua escolha).\n  - **Opção 2 - Passo do Enxame:** O enxame movimenta você para uma posição segura. Você pode se mover imediatamente **1,5 metro [5 pés]** horizontalmente para um espaço desocupado. Esse movimento não provoca **Ataques de Oportunidade**.\n  - **Opção 3 - Investida Grudenta:** O enxame tenta sobrecarregar o alvo. A criatura atingida deve realizar um Teste de Resistência de **Força** contra a sua **CD de [Segredos de Caçador](tbClassehabilidade, cacador, segredos-de-cacador)**. Em uma falha, o deslocamento da criatura é reduzido pela **metade** e ela não pode usar **Reações** até o início do seu próximo turno.","id_classe_id":4,"id_habilidade":1029,"id_subclasse_id":116,"niveladquirido":3,"nome":"Enxame Simbiótico","nome_ingles":null,"table_only":false,"tags_json":["trigger=hit_melee","1/turn","instant{ pick:efeito_enxame:1 }","define{efeito_enxame: list{ assalto_rastejante:{dmg:+resource{dado_de_cacador}(pick:{perfurante | necrotico})}, passo_do_enxame:{instant{teleport:5ft(without{aoo})}}, investida_grudenta:{save:str, cd=ability{segredos_de_cacador, classe:cacador}.cd, on_fail:{speed:half, restricts{reaction}}, duration:until_turn_start} }}"]},{"descricao":"*\"Com o tempo, deixei de pensar neles como ''meu enxame'' e passei a pensar como ''nós''. Se eu escalo, sou carregado. Se eu paro, eles vigiam.\"*\n  Seu corpo e o enxame operam em uma consciência compartilhada permanente.\n- **Enxame Arcano:** Você aprende o truque **Mãos Mágicas [Mage Hand]**. Quando você conjura essa magia, a mão assume a forma de uma porção do seu enxame. Você usa seu modificador de **Sabedoria** ou **Inteligência** como atributo de conjuração para ela.\n- **Sentidos Coletivos:** Você não pode ser **Surpreendido** enquanto não estiver **Inconsciente**, pois o enxame alerta você de perigos próximos.\n- **Escalada Orgânica:** Você ganha um **Deslocamento de Escalada** igual ao seu Deslocamento de Caminhada. Você pode escalar superfícies verticais e tetos sem precisar realizar testes de Habilidade, desde que tenha ao menos uma mão livre ou o auxílio do enxame.","id_classe_id":4,"id_habilidade":1030,"id_subclasse_id":116,"niveladquirido":3,"nome":"Simbiose do Enxame","nome_ingles":null,"table_only":false,"tags_json":["always_active{ immune_effect:surprise(requires:not{condition{inconsciente, target:self}}), move:climb, move:wall }","cast{spell:mao-arcana, always_prepared, modifiers{spell_mod}}"]},{"descricao":"*\"No começo, eu só via o contorno. Com o tempo, passei a enxergar o resto: a mudança de peso no passo, o brilho de olho com medo. A escuridão continua lá, mas pra mim ela só esconde quem quer ser pego.\"*\n  Você desenvolve sentidos sobrenaturais adaptados à ausência total de luz.\n- **Visão no Escuro Superior:** Você ganha **Visão no Escuro** com alcance de **18 metros [60 pés]**. Se você já possuir Visão no Escuro proveniente de sua raça, o alcance dela aumenta em **9 metros [30 pés]**.\n- **Olhos na Escuridão:** Você consegue enxergar através de qualquer **Escuridão**, seja ela mágica ou não mágica. Para você, áreas de escuridão a até **18 metros [60 pés]** são tratadas como **Penumbra**. Você enxerga formas e criaturas nessas áreas normalmente.","id_classe_id":4,"id_habilidade":1031,"id_subclasse_id":117,"niveladquirido":3,"nome":"Visão Umbral","nome_ingles":null,"table_only":false,"tags_json":["always_active{ sense:darkvision(range:60ft) }"]},{"descricao":"*\"Eu não corro pra chegar depois. Eu já estou lá quando o resto decide que é hora de lutar. O primeiro suspiro pesado, o primeiro olhar na direção errada… é aí que eu entro.\"*\n  Você domina a arte de atacar antes que o inimigo perceba o perigo.\n- **Instinto de Abertura:** Sempre que você realizar uma **Jogada de Iniciativa**, você adiciona seu modificador de **Sabedoria** ou **Inteligência** ao resultado (mínimo de +1).\n- **Explosão do Primeiro Golpe:** No seu primeiro turno de cada combate, se você realizar a ação **Atacar**, você pode fazer **1 Ataque Adicional** com arma como parte da mesma ação.\n- **Dano Escalonado:** Se esse ataque adicional acertar, ele causa dano extra igual ao seu **Nível de Caçador**. Este dano é do mesmo tipo da arma utilizada.\n- **Limite:** Os benefícios desta característica aplicam-se apenas ao turno imediatamente posterior à sua rolagem de iniciativa.","id_classe_id":4,"id_habilidade":1032,"id_subclasse_id":117,"niveladquirido":3,"nome":"Emboscada Sombria","nome_ingles":null,"table_only":false,"tags_json":["trigger=first_turn, requires:action{attack}, attacks:+1{weapon}","next_attack.dmg:+classlvl(weapon_type)","initiative:+max(1, spell_mod)"]},{"descricao":"*\"Depois de um tempo tomando coisa que queimaria um homem comum por dentro, o corpo muda. A pele engrossa, o sangue aprende a lidar com veneno. Não é bonito. Mas funciona.\"*\n  Seu corpo foi permanentemente alterado pelos experimentos alquímicos, tornando-se mais resistente e robusto.\n- **Vitalidade Aumentada:** Seu máximo de **Pontos de Vida** aumenta em uma quantidade igual ao seu **Nível de Caçador**. Sempre que você ganhar um nível nesta classe, seu máximo de Pontos de Vida aumenta em **1** adicional.\n- **Corpo Adaptado:** Você ganha **Imunidade** a dano de **Veneno** e à condição **Envenenado**.","id_classe_id":4,"id_habilidade":1033,"id_subclasse_id":112,"niveladquirido":3,"nome":"Fisiologia Mutante","nome_ingles":null,"table_only":false,"tags_json":["always_active{ buff:max_hp:+classlvl }","immune:veneno","cond_immune:envenenado"]},{"descricao":"*\"Cada frasco é uma aposta: se eu aguentar, viro algo novo. Se não aguentar… bom, por isso testo em mim mesmo e não nos outros.\"*\n  Você domina a criação de elixires que alteram temporariamente sua biologia.\n- **Fórmulas Conhecidas:** Você aprende **4 Fórmulas Mutagênicas** da lista da Ordem dos Mutantes (detalhada a seguir). Você aprende fórmulas adicionais quando alcança os níveis **7**, **11**, **15** e **18** de Caçador. Sempre que aprender uma nova fórmula, você pode substituir uma que já conhece por outra da lista.\n- **Preparação:** Ao terminar um **Descanso Curto** ou **Descanso Longo**, você pode preparar um número limitado de mutagênicos usando seu kit de alquimia. Os frascos duram até o seu próximo descanso, momento em que se tornam inertes se não forem usados. O número de mutagênicos que você pode ter prontos depende do seu nível:\n  - Nível 3: **1 Mutagênico**\n  - Nível 7: **2 Mutagênicos**\n  - Nível 15: **3 Mutagênicos**\n- **Consumo e Ativação:** Como uma **Ação Bônus**, você pode consumir ou injetar um mutagênico preparado. Ao fazer isso, você recebe imediatamente o **Efeito Benéfico** e o **Efeito Colateral** da fórmula.\n- **Duração:** Os efeitos duram até você terminar um **Descanso Curto** ou **Descanso Longo**. Alternativamente, você pode usar uma **Ação** para purgar as toxinas do seu sistema, encerrando todos os efeitos (benéficos e colaterais) de todos os mutagênicos ativos.\n- **Toxicidade Específica:** Os mutagênicos são calibrados para a sua biologia específica. Se outra criatura tentar consumir um de seus mutagênicos, ela não recebe nenhum benefício e deve ser bem-sucedida em um Teste de Resistência de **Constituição** (CD igual à sua **CD de [Segredos de Caçador](tbClassehabilidade, cacador, segredos-de-cacador)**) ou ficará **Envenenada** por **1 hora**.\n##### Mutagênico de Carapaça de Basilisco\n**A espessa carapaça do basilisco possui uma estrutura cristalina que distribui impactos com eficiência, endurecendo sua pele mas comprometendo sua mobilidade.**\n- **Efeito Benéfico:** Você ganha **resistência a dano cortante, perfurante e concussivo**.\n- **Efeito Colateral:** Sua **velocidade de movimento é reduzida em 3 metros [10 pés]**.\n##### Mutagênico de Kraken Onisciente\n*O consumo do fluido cerebral de cefalópodes abissais expande a massa cinzenta e a condutividade sináptica, permitindo processamento lógico sobre-humano, mas causa atrofia muscular severa devido ao consumo energético do cérebro.*\n- **Efeito Benéfico:** Sua pontuação de **Inteligência** aumenta em **+3**, assim como seu limite máximo de Inteligência. Nos níveis 11 e 18 de caçador, esse bônus aumenta em **+1**.\n- **Efeito Colateral:** Sua pontuação de **Força** diminui em **-3**.\n##### Mutagênico de Esfinge Visionária\n*Inspirado na percepção sobrenatural das esfinges, este mutagênico reconecta o sistema nervoso para \"sentir\" a verdade e o ambiente, sobrecarregando a intuição em detrimento do raciocínio lógico linear.*\n- **Efeito Benéfico:** Sua pontuação de **Sabedoria** aumenta em **+3**, assim como seu limite máximo de Sabedoria. Nos níveis 11 e 18 de caçador, esse bônus aumenta em **+1**.\n- **Efeito Colateral:** Sua pontuação de **Inteligência** diminui em **-3**.\n##### Mutagênico de Salamandra Ígnea\n**As glândulas térmicas da salamandra ígnea oferecem proteção contra calor extremo, mas sua instabilidade térmica torna o corpo vulnerável ao frio.**\n- **Efeito Benéfico:** Você ganha **resistência a dano de fogo**.\n- **Efeito Colateral:** Você sofre **vulnerabilidade a dano de frio**.\n##### Mutagênico de Raptor Sombrio\n**A mutação com base nos tendões do raptor sombrio concede reflexos acentuados e uma agilidade animalesca, ao custo de estabilidade mental.**\n- **Efeito Benéfico:** Sua pontuação de Destreza aumenta em +3, assim como seu limite máximo de Destreza. Nos níveis 11 e 18 de caçador, esse bônus aumenta em +1.\n- **Efeito Colateral:** Sua pontuação de Sabedoria diminui em -3.\n##### Mutagênico de Yeti Boreal\n**A gordura densa e os pelos resistentes do yeti criam uma barreira natural contra o frio, mas inibem o corpo de dissipar calor.**\n- **Efeito Benéfico:** Você ganha **resistência a dano de frio**.\n- **Efeito Colateral:** Você sofre **vulnerabilidade a dano de fogo**.\n##### Mutagênico de Vermeluz das Cavernas\n**Derivado da estrutura flexível dos vermes gigantes subterrâneos, esse mutagênico permite que o corpo escape de contenções físicas com facilidade, mas enfraquece o desempenho físico bruto.**\n- **Efeito Benéfico:** Você se torna **imune às condições Agarrado e Restringido**. No 11º nível de caçador, você também é imune à condição Paralisado.\n- **Efeito Colateral:** Você tem **desvantagem em testes de Força** e **não pode Agarrar criaturas**.\n##### Mutagênico de Morcego Abissal\n**A mutação replica o sistema sensorial avançado dos morcegos das profundezas, expandindo a visão noturna ao custo de sensibilidade extrema à luz.**\n- **Efeito Benéfico:** Você ganha **visão no escuro de 18 metros [60 pés]**. Se já possuir visão no escuro, ela aumenta em +18 metros [60 pés].\n- **Efeito Colateral:** Você sofre de **sensibilidade à luz intensa**, tendo desvantagem em testes de habilidade e ataques feitos sob iluminação plena.\n##### Mutagênico de Lobo Alfa\n**As glândulas sensoriais ampliadas do lobo alfa aprimoram os sentidos auditivo e olfativo, mas criam um comportamento de alerta hostil, dificultando a interação social.**\n- **Efeito Benéfico:** Você tem **vantagem em testes de Sabedoria (Percepção) baseados em olfato, visão ou audição**.\n- **Efeito Colateral:** Você tem **desvantagem em testes de Carisma (Persuasão, Enganação, Intimidação ou Atuação)**.\n##### Mutagênico de Górgona Prateada\n**A górgona concentra força bruta em cada músculo tenso, tornando o corpo mais poderoso, mas menos responsivo aos reflexos ágeis.**\n- **Efeito Benéfico:** Sua pontuação de Força aumenta em +3, assim como seu limite máximo. Nos níveis 11 e 18 de caçador, esse bônus aumenta em +1.\n- **Efeito Colateral:** Sua pontuação de Destreza diminui em -3.\n##### Mutagênico de Guepardo das Planícies\n**A mutação altera os tendões e a composição óssea, permitindo maior aceleração e movimentação — mas causa instabilidade mental sob pressão.**\n- **Efeito Benéfico:** Sua velocidade de movimento aumenta em +3 metros [10 pés]. No 15º nível de caçador, ela aumenta em +4,5 metros [15 pés].\n- **Efeito Colateral:** Você tem **desvantagem em testes de Inteligência** e **não pode manter concentração em magias ou rituais**.\n##### Mutagênico de Camaleão Espectral\n**As adaptações de pigmentação da pele e modulação vocal do camaleão permitem alterações sutis de aparência e entonação, melhorando a performance social — ao custo da prontidão combativa.**\n- **Efeito Benéfico:** Você pode usar seu modificador de **Sabedoria** ou **Inteligência** em **testes de Carisma**.\n- **Efeito Colateral:** Você tem **desvantagem em testes de Iniciativa**.\n##### Mutagênico de Lagartixa-Cicatrizante\n**Pré-requisito:** 7º nível de Caçador\n **Essa mutação ativa enzimas regenerativas inspiradas nas lagartixas cicatrizantes. Seu corpo cura por si só — mas rejeita outras formas de cura.**\n- **Efeito Benéfico:** Durante 1 hora, no início de cada um de seus turnos, você recupera **pontos de vida iguais ao seu bônus de Proficiência**, se estiver com pelo menos 1 ponto de vida.\n- **Efeito Colateral:** **Todas as curas externas em você têm seu valor reduzido pela metade**.\n##### Mutagênico de Manticora Raivosa\n**Pré-requisito:** 11º nível de Caçador\n **A mutação simula os efeitos da glândula de raiva da manticora, permitindo ataques mais rápidos à custa do controle mental.**\n- **Efeito Benéfico:** Sempre que usar a ação de Ataque, você pode realizar um **ataque adicional com uma ação bônus**.\n- **Efeito Colateral:** Você tem **desvantagem em testes de resistência de Inteligência, Sabedoria e Carisma**.\n##### Mutagênico de Harpia das Montanhas\n**Pré-requisito:** 11º nível de Caçador\n **As fibras leves e membranas adaptadas da harpia permitem voo por tempo limitado. Contudo, o foco necessário para sustentar o voo compromete sua mira.**\n- **Efeito Benéfico:** Você ganha **voo igual à sua velocidade de movimento** por 1 hora.\n- **Efeito Colateral:** Você tem **desvantagem em jogadas de ataque com armas** por 1 hora.\n##### Mutagênico de Quimera do Caos\n**Pré-requisito:** 11º nível de Caçador\n **A fúria da quimera altera seu ritmo de combate, canalizando sua selvageria em precisão instintiva.**\n- **Efeito Benéfico:** Seus ataques com arma **acertam criticamente em 19 ou 20**.\n- **Efeito Colateral:** Você tem **desvantagem em testes de resistência contra efeitos mentais** (como encantamento ou medo).","id_classe_id":4,"id_habilidade":1034,"id_subclasse_id":112,"niveladquirido":3,"nome":"Fórmulas Mutagênicas","nome_ingles":null,"table_only":false,"tags_json":["spell_selection:fonte:mutagenicos{ qtd:{classlvl=3:4, classlvl=7:1, classlvl=11:1, classlvl=15:1, classlvl=18:1} }","pick:mutagenico_preparado:{classlvl=3:1, classlvl=7:2, classlvl=15:3}","reset:rest","action=bonus_action","instant{ activate:defined{mutagenico_preparado}(target:self, pick:1) }","while_active{action:action, instant{end:defined{mutagenico_preparado}(target:self, all)}}","define{mutagenico_preparado: list{ carapaca_basilisco:{resist:cortante, resist:perfurante, resist:concussao, speed:-10}, kraken:{attr:int_score+match(classlvl){classlvl>=18:5, classlvl>=11:4, default:3}, attr_max:int, attr:str_score_3}, esfinge:{attr:wis_score+match(classlvl){classlvl>=18:5, classlvl>=11:4, default:3}, attr_max:wis, attr:int_score_3}, salamandra:{resist:fogo, vuln:frio}, raptor:{attr:dex_score+match(classlvl){classlvl>=18:5, classlvl>=11:4, default:3}, attr_max:dex, attr:wis_score_3}, yeti:{resist:frio, vuln:fogo}, vermeluz:{cond_immune:agarrado, cond_immune:restringido, cond_immune:paralisado(requires:classlvl>=11), dadv:check{forca}}, morcego:{sense:darkvision(range:60ft)}, lobo_alfa:{adv:check{percepcao}, dadv:check{persuasao}, dadv:check{enganacao}, dadv:check{intimidacao}, dadv:check{atuacao}}, gorgona:{attr:str_score+match(classlvl){classlvl>=18:5, classlvl>=11:4, default:3}, attr_max:str, attr:dex_score_3}, guepardo:{speed:+match(classlvl){classlvl>=15:25, default:10}}, camaleao:{check_attr:carisma:=spell_mod, dadv:initiative}, lagartixa:{trigger=turn_start, instant{heal:pb}, duration:600}, manticora:{action:bonus_action, instant{attack}, dadv:save{int}, dadv:save{wis}, dadv:save{cha}}, harpia:{move:fly}, quimera:{crit_range:+1, dadv:save{mental}} }}"]},{"descricao":"*Treinar não é polir espelhos; é engrossar a madeira do arco que me sustenta. Anoto cada sessão como quem corta lenha, sem pressa e sem vaidade, porque é o esforço repetido, e não o talento súbito, que aguenta o peso quando a caçada aperta de verdade contra mim.*\n\nVocê pode aumentar um valor de atributo em **2**, ou dois valores de atributo em **1** cada, até o máximo de **20**; ou então escolher um **Talento** para o qual cumpra os pré-requisitos. Você ganha esta característica novamente nos níveis **8**, **12**, **16** e **19**.","id_classe_id":4,"id_habilidade":1035,"id_subclasse_id":null,"niveladquirido":4,"nome":"Aprimoramento de Atributo ou Talento","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Onde antes eu acertava um golpe, hoje desfecho dois antes que a presa entenda o primeiro. A trilha me ensinou que uma única lâmina raramente basta contra o que persigo, então treinei o braço até o segundo ataque nascer do primeiro sozinho, sem que eu precise sequer pensar.*\n\nVocê pode atacar duas vezes, em vez de uma, sempre que usar a ação Atacar (Attack) no seu turno.","id_classe_id":4,"id_habilidade":1036,"id_subclasse_id":null,"niveladquirido":5,"nome":"Ataque Extra","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Onde eu piso já não é território deles; é meu. Aprendi a ler cada floresta, montanha ou beco como se eu mesmo tivesse desenhado o mapa: sei onde a água corre, onde o vento entrega o cheiro e por onde a presa vai tentar escapar antes de falhar.*\n\nVocê se tornou exímio em transformar qualquer ambiente em terreno familiar. A partir do 5º nível, você ganha os benefícios a seguir enquanto estiver explorando ambientes naturais ou urbanos selvagens, como florestas, montanhas, pântanos, desertos, subterrâneos e ruínas:\n\n- **Movimento Desimpedido.** O terreno difícil não mágico não reduz a sua velocidade nem a dos seus companheiros enquanto você os guia.\n\n- **Senso de Direção.** Você nunca se perde por meios não mágicos.\n\n- **Vigilância Constante.** Mesmo quando ocupado com outra atividade, como ler, cozinhar ou conversar, você permanece atento e não pode ser pego desprevenido enquanto estiver consciente, mesmo durante um Descanso Curto.\n\n- **Passos Silenciosos.** Quando está sozinho, você pode mover-se em ritmo normal sem deixar rastros e em silêncio.\n\n- **Abundância.** Ao forragear ou caçar para alimentar o grupo, você encontra o dobro do que normalmente encontraria.\n\n- **Rastreador Analítico.** Ao examinar trilhas, você determina automaticamente o número aproximado de criaturas, o tamanho delas e há quanto tempo passaram.","id_classe_id":4,"id_habilidade":1037,"id_subclasse_id":null,"niveladquirido":5,"nome":"Território de Caça","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*\"Não preciso chamá-lo. Ele sente quando estou pronto para o golpe. Há uma linha invisível entre nós, traçada por rastros, caçadas passadas e silêncios partilhados. Quando avanço, ele já está em movimento. Quando hesito, ele recua comigo.\"*\n  Sua conexão com o Espírito Primordial transcende comandos verbais, permitindo uma coordenação ofensiva e defensiva perfeita.\n- **Instinto Compartilhado:** Enquanto o seu Espírito Primordial puder ver você, ele tem **Vantagem** em todos os **Testes de Resistência**.\n- **Ataque Coordenado:** Quando você realizar a ação **Atacar** no seu turno, você pode substituir um dos seus ataques por um ataque corpo a corpo do seu Espírito Primordial. Para isso, o espírito deve ser capaz de ver você e você não precisa usar sua **Ação Bônus** para comandá-lo a fazer este ataque específico.","id_classe_id":4,"id_habilidade":1039,"id_subclasse_id":21,"niveladquirido":6,"nome":"Elo de Caça Rúnica","nome_ingles":null,"table_only":false,"tags_json":["always_active{companion.adv:save}","while_active{requires:action{attack}, attacks:-1{instant{grant:companion_command{attack:melee}}}}"]},{"descricao":"*\"Gravei um símbolo com cinzas e prata na bainha. Primeiro achei que fosse superstição. Aí vi um demônio tentar sumir no meio do golpe… e bater no próprio ar. Desde então, toda presa marcada sabe: se tentar fugir, eu travo.\"*\n  Você aprende a invocar proteções rúnicas instantâneas contra a magia e a fúria de suas presas.\n- **Gatilho:** Uma criatura que esteja sob efeito da sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)** ou que pertença a um tipo de criatura escolhido na sua característica **Presa Estudada** realiza uma das seguintes ações contra você: conjura uma magia, usa uma ação mágica, tenta se teletransportar, tenta mudar de plano ou acerta você com um ataque corpo a corpo ou com arma.\n- **Reação de Defesa:** Quando o gatilho ocorrer, você pode usar sua **Reação** para ativar a ruptura. O efeito depende da ação do inimigo:\n  - **Teleporte e [Viagem Planar](tbMagia, viagem-planar):** A criatura deve ser bem-sucedida em um Teste de Resistência de **Sabedoria** ou **Inteligência** contra a sua **CD de [Segredos de Caçador](tbClassehabilidade, cacador, segredos-de-cacador)**. Em uma falha, o teleporte ou mudança de plano falha e o recurso ou ação da criatura é gasto sem efeito.\n  - **Magia Ofensiva:** Se a criatura causar dano a você com uma magia ou efeito mágico, você ganha **Resistência** a todo o dano causado por esse efeito e tem **Vantagem** no Teste de Resistência exigido pela magia.\n  - **Ataque Físico:** Se a criatura acertar um ataque corpo a corpo ou com arma, você ganha **Resistência** a todo o dano causado por esse ataque.\n- **Usos:** Você pode usar esta característica um número de vezes igual ao seu modificador de **Sabedoria** ou **Inteligência** (mínimo de 1). Você recupera todos os usos gastos ao terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1040,"id_subclasse_id":118,"niveladquirido":6,"nome":"Ruptura Rúnica","nome_ingles":null,"table_only":false,"tags_json":["action=reaction","trigger=hit_by_attack(source:{mark:ability{marca_do_cacador, classe:cacador} | chosen_enemies})","instant{ resist:source }","trigger=target_deal_magic_dmg(source:{mark:ability{marca_do_cacador, classe:cacador} | chosen_enemies}), instant{ resist:source, adv:save{source} }","trigger=teleport_attempt(source:{mark:ability{marca_do_cacador, classe:cacador} | chosen_enemies}), instant{ save{wis|int, cd=ability{segredos_de_cacador, classe:cacador}.cd}, on_fail:{ cancel:teleport } }","uses{max(1, spell_mod), reset:long_rest}"]},{"descricao":"*\"Quando a lâmina veio, eu já tinha o símbolo pronto na palma. O aço atravessou um pedaço de nada, o impacto morreu no meio do caminho… e a força voltou para o lado errado. Não é sobre bloquear. É sobre devolver.\"*\n  Você aprende a dobrar o espaço para absorver impactos e redirecionar a energia cinética contra seus inimigos.\n- **Gatilho:** Uma criatura que esteja sob o efeito da sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)** ou que pertença a um tipo escolhido na sua característica **Presa Estudada** acerta você com um ataque corpo a corpo ou à distância.\n- **Redução de Dano:** Você pode usar sua **Reação** para reduzir o dano desse ataque. O valor da redução é igual a **1d10** + seu modificador de **Sabedoria** ou **Inteligência** (o atributo escolhido ao ingressar na Ordem) + seu **Nível de Caçador**. Se restar dano após a redução, você o sofre normalmente.\n- **Retaliação Planar:** Se esta característica reduzir o dano do ataque a **0**, você pode redirecionar a energia. Escolha uma criatura hostil que você possa ver a até **18 metros [60 pés]** de você. O alvo deve realizar um Teste de Resistência de **Destreza** contra a sua **CD de [Segredos de Caçador](tbClassehabilidade, cacador, segredos-de-cacador)**. Em uma falha, sofre dano de **Energia (Força)** igual a **2 Dados de Caçador** + seu modificador de habilidade escolhido. Em um sucesso, sofre metade do dano.\n- **Usos:** Você pode usar esta característica um número de vezes igual ao seu modificador de **Sabedoria** ou **Inteligência** (mínimo de 1). Você recupera todos os usos gastos ao terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1041,"id_subclasse_id":115,"niveladquirido":6,"nome":"Ruptura de Selo","nome_ingles":null,"table_only":false,"tags_json":["action=reaction","trigger=hit_by_attack(source:{mark:ability{marca_do_cacador, classe:cacador} | chosen_enemies})","instant{ dmg_reduction:1d10+spell_mod+classlvl }","trigger=if(dmg_reduced_to_0): instant{ aoe{ point(range:60ft), target:enemies, save{dex, cd=ability{segredos_de_cacador, classe:cacador}.cd}, dmg:2(resource{dado_de_cacador})+spell_mod(forca), on_success:half } }","uses{max(1, spell_mod), reset:long_rest}"]},{"descricao":"*\"Teve um dia em que eu jurei ter sido rápido o bastante para desviar de uma flecha. Depois percebi que não fui eu. Eles se moveram antes. Desde então, não sei mais onde eu termino e onde eles começam.\"*\n  O enxame passa a agir de forma autônoma para preservar a vida do hospedeiro.\n- **Barreira Viva (Passiva):** Uma vez por turno, quando você sofreria dano de qualquer fonte, você calcula o valor total do dano. Se esse valor for igual ou menor que seu modificador de **Sabedoria** ou **Inteligência** (à sua escolha, mínimo +1) somado ao seu **Nível de Caçador**, o dano é reduzido a **0**. Se o dano for superior a esse total, você sofre o dano completo. O enxame se dispersa momentaneamente após absorver o impacto.\n- **Resposta Instintiva (Reação):** Quando uma criatura que você possa ver a até **9 metros [30 pés]** realizar uma jogada de ataque contra você ou contra um aliado a até **1,5 metro [5 pés]** de você, você pode usar sua **Reação** para intervir. O enxame impõe **Desvantagem** na jogada de ataque. Além disso, você pode mover a criatura alvo do ataque em até **1,5 metro [5 pés]** para qualquer espaço desocupado. Esse movimento não provoca **Ataques de Oportunidade**.\n- **Usos:** Você pode usar a Resposta Instintiva um número de vezes igual ao seu modificador de **Sabedoria** ou **Inteligência** (mínimo de 1). Você recupera todos os usos gastos ao terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1042,"id_subclasse_id":116,"niveladquirido":6,"nome":"Instinto Coletivo","nome_ingles":null,"table_only":false,"tags_json":["always_active{trigger=take_damage, 1/turn, instant{if(dmg_total <= max(1, spell_mod)+classlvl): dmg_reduction:all}}","action=reaction","trigger=hit_by_attack(target:{self | ally(range:5ft)}, source_range:30ft)","instant{ source.dadv:attack, push:5ft(target:{self | ally(range:5ft)}) }","uses{max(1, spell_mod), reset:long_rest}"]},{"descricao":"*\"Eles juram que olharam na minha direção. Mas ninguém acerta o lugar certo. Na penumbra, eu não sou pessoa — sou dúvida.\"*\n  Você se torna um mestre da furtividade estática e do movimento imperceptível.\n- **Sumir no Breu:** Quando você realizar a ação **Esconder** estando em uma área de **Penumbra** ou **Escuridão**, se o teste for bem-sucedido, você ganha a condição **Invisível**. Esta invisibilidade dura até o início do seu próximo turno, ou termina prematuramente se você realizar um ataque, conjurar uma magia ou se mover voluntariamente.\n- **Ocultação Sobrenatural:** Enquanto estiver sob o efeito desta invisibilidade, você permanece **Invisível** até mesmo para criaturas que dependam de **Visão no Escuro** para enxergar você. Apenas sentidos especiais (como **Visão às Cegas** ou **Sentido Sísmico**) podem detectá-lo.\n- **Deslocamento sem Brecha:** Uma vez por rodada, enquanto estiver em **Escuridão**, você pode se mover até **3 metros [10 pés]** durante o seu turno. Esse movimento não provoca **Ataques de Oportunidade**.","id_classe_id":4,"id_habilidade":1043,"id_subclasse_id":117,"niveladquirido":6,"nome":"Manto das Sombras","nome_ingles":null,"table_only":false,"tags_json":["trigger=hide_action, requires:in_dim_light, instant{apply:invisivel(target:self)}","duration:until_turn_start","while_active{action:free, instant{move:10ft(without{opportunity_attack})}, 1/turn, requires:in_darkness}"]},{"descricao":"*\"Nem toda mutação manda em mim. Respiro fundo, ativo o que destilei pra isso… e, por um tempo, sou eu quem manda no frasco. Não o contrário.\"*\n  Você desenvolve o controle fisiológico necessário para ignorar temporariamente a toxicidade de seus próprios elixires.\nEnquanto estiver sob o efeito de pelo menos 1 **Mutagênico**, você pode usar uma **Ação Bônus** para suprimir seus efeitos nocivos.\n- **Supressão Temporária:** Escolha um mutagênico ativo em você. Por **1 minuto**, você ignora totalmente o **Efeito Colateral** dessa fórmula, mas mantém o **Efeito Benéfico**. O mutagênico continua contando como ativo para fins de limites de toxicidade.\n- **Recuperação:** Uma vez que você use esta característica, não pode usá-la novamente até terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1044,"id_subclasse_id":112,"niveladquirido":6,"nome":"Supressão Alquímica","nome_ingles":null,"table_only":false,"tags_json":["action=bonus_action","requires:active{defined{mutagenico_preparado}}","instant{ suppress:active{defined{mutagenico_preparado}}.efeito_colateral(pick:1) }","duration:10","resource_cost:1/long_rest"]},{"descricao":"*Quem corre comigo cansa; quem foge de mim cansa duas vezes. Aprendi a mover o corpo como água em correnteza — se a presa dispara, aperto o passo; se ela escala, acho onde pôr a mão — porque não existe longe demais, só distância que ainda não foi fechada.*\n\nSua mobilidade e resistência se aprimoram:\n\n- **Passo Alongado.** Sua velocidade de caminhada aumenta em **3 metros [10 pés]**.\n\n- **Mobilidade Adaptada.** Você ganha velocidade de escalada e de natação iguais à sua velocidade de caminhada.\n\n- **Disparada Veloz.** Você pode usar a ação Disparar (Dash) como uma Ação Bônus.","id_classe_id":4,"id_habilidade":1045,"id_subclasse_id":null,"niveladquirido":7,"nome":"Caçador Implacável","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Minha mente vigia o que meu corpo não vê chegar. Percebi na pele que a caçada não se ganha só com as pernas: quando a dor pesa, é a cabeça que decide se eu caio ou continuo, então aprendi a deixá-la comandar o resto sempre que os sentidos falham.*\n\nSua mente afiada protege seu corpo. Você adiciona o seu modificador de Inteligência ou Sabedoria, o que for sua habilidade de conjuração, aos seus testes de resistência de Força, Destreza e Constituição. Você também ganha uma perícia adicional afetada pelo Instinto de Caçador do 3º nível.","id_classe_id":4,"id_habilidade":1047,"id_subclasse_id":null,"niveladquirido":9,"nome":"Instinto Afiado","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*\"Feras não atacam ao acaso. Elas cercam, testam, encurralam. No meio do caos, nós dois nos movemos como um anel de dentes fechando em um único golpe.\"*\n  Seu espírito aprende a lidar com múltiplos inimigos simultaneamente, girando em um redemoinho de garras e dentes.\n- **Golpe em Círculo:** Quando você comandar o espírito a atacar, ou usar a característica **Ataque Coordenado**, o espírito pode realizar um ataque corpo a corpo separado contra cada criatura à escolha dele que esteja a até **1,5 metro [5 pés]** dele. Cada ataque utiliza uma jogada de ataque separada.\n- **Recuperação:** Após usar essa característica, você não pode usá-la novamente até terminar um **Descanso Curto** ou **Descanso Longo**.\n- **Empoderar com Segredos:** Se você não tiver usos disponíveis dessa característica, você pode gastar **2 Pontos de Segredo** para usá-la novamente.","id_classe_id":4,"id_habilidade":1049,"id_subclasse_id":21,"niveladquirido":10,"nome":"Cerco de Presas Rituais","nome_ingles":null,"table_only":false,"tags_json":["instant{grant:companion_command{attack:melee(target:enemies(range:5ft, from:companion))}}","resource_cost:1/short_rest","resource_cost:pontos_de_segredo:2"]},{"descricao":"*\"Quando o fio da lâmina encontra o primeiro alvo, eu já estou pensando no segundo. A carne do primeiro só abre o caminho: o resto sente o impacto como um sino batido dentro do osso.\"*\n  Seus ataques contra alvos marcados reverberam, punindo criaturas semelhantes que estejam próximas.\n- **Gatilho:** Uma vez em cada um dos seus turnos, quando você acertar uma jogada de ataque contra uma criatura afetada pela sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)**.\n- **Dano em Cadeia:** Todas as criaturas hostis que sejam do **mesmo Tipo de Criatura** do alvo marcado e estejam a até **3 metros [10 pés]** dele sofrem dano automático. O dano é igual a uma rolagem do seu **Dado de Caçador** (o dado de dano extra da Marca). O tipo de dano é o mesmo do ataque que ativou o efeito.\n- **Bônus de Presa Estudada:** Se as criaturas afetadas pelo Eco Purgante também pertencerem a um tipo escolhido na sua característica **Presa Estudada**, elas sofrem dano adicional igual ao bônus concedido por aquela característica (+2, ou +4 se você for de 6º nível ou superior).\n- **Restrição:** Este efeito não afeta seus aliados, nem criaturas que não compartilhem o tipo da criatura marcada.","id_classe_id":4,"id_habilidade":1050,"id_subclasse_id":118,"niveladquirido":10,"nome":"Eco Purgante","nome_ingles":null,"table_only":false,"tags_json":["trigger=hit_melee, requires:target{mark:ability{marca_do_cacador, classe:cacador}}","1/turn","instant{ aoe{ radius:10ft(from:target), target:enemies(same_creature_type), dmg:1(resource{dado_de_cacador})(same_type_as_trigger) } }","dmg:+match(classlvl){classlvl>=6:4, default:2}(requires:target{chosen_enemies})"]},{"descricao":"*\"Com um corte eu marco, com o outro eu sumo. O campo vira um mapa de portas abertas: cada runa é um passo adiante, cada inimigo, um ponto de chegada.\"*\n  Seu domínio sobre as [Runas de Travessia](tbClassehabilidade, ordem-dos-viajantes, runas-de-travessia) permite um estilo de combate de alta mobilidade, transformando cada golpe em uma oportunidade de reposicionamento.\n- **Salto Ampliado:** Sempre que você realizar uma jogada de ataque com arma contra uma criatura no seu turno, imediatamente após resolver o ataque (acertando ou errando), você pode se teletransportar para um espaço desocupado que você possa ver a até **3 metros [10 pés]**. Este teleporte não provoca **Ataques de Oportunidade**.\n- **Golpe em Cadeia:** Uma vez por turno, imediatamente após o teleporte, se houver uma criatura inimiga diferente dentro do alcance da arma utilizada, você pode realizar **1 Ataque Adicional** contra ela como parte da mesma ação. Este ataque segue as regras normais, incluindo benefícios da sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)**.\n- **Restrições:** Você não pode usar este benefício se seu deslocamento for **0** ou se estiver impedido de se teletransportar. Você deve terminar o teleporte em um espaço onde seu corpo caiba fisicamente.","id_classe_id":4,"id_habilidade":1051,"id_subclasse_id":115,"niveladquirido":10,"nome":"Salto de Travessia","nome_ingles":null,"table_only":false,"tags_json":["trigger=action{attack:weapon}, instant{teleport:10ft(without{aoo})}","1/turn","instant{ attacks:+1(requires:enemies(range:weapon_reach)) }"]},{"descricao":"*\"Eles começaram pequenos: um zumbido no ombro. Agora sinto o corpo andar com mais do que só meu próprio peso. Quando eu avanço, o campo inteiro sabe que não dá mais pra fingir que eles são só insetos.\"*\n  Seu vínculo com o enxame se aprofunda, aprimorando suas capacidades ofensivas e defensivas.\n- **Assalto Rastejante Aprimorado:** Quando uma criatura falhar no Teste de Resistência contra seu Assalto Rastejante, ela também fica com a condição **Envenenado** até o início do seu próximo turno.\n- **Investida Grudenta Aprimorada:** Quando uma criatura falhar no Teste de Resistência contra sua Investida Grudenta, além dos efeitos normais, você pode derrubá-la, deixando-a com a condição **Caído**.\n- **Passo do Enxame Reforçado:** Ao usar o Passo do Enxame, você ganha **Meia Cobertura** (+2 na CA e Testes de Resistência de Destreza) até o início do seu próximo turno.\n- **Força Multiplicada:** Sempre que você realizar um teste de **Força (Atletismo)** para empurrar, agarrar ou evitar ser agarrado, você adiciona uma rolagem do seu **Dado de Caçador** ao resultado.\n- **Predador da Presa:** Criaturas que pertençam a um tipo escolhido na sua característica **Presa Estudada** têm **Desvantagem** nos Testes de Resistência contra todos os efeitos do seu **[Enxame Simbiótico](tbClassehabilidade, ordem-do-enxame, enxame-simbiotico)**.","id_classe_id":4,"id_habilidade":1052,"id_subclasse_id":116,"niveladquirido":10,"nome":"Enxame Expansivo","nome_ingles":null,"table_only":false,"tags_json":["modify:ability{enxame_simbiotico, classe:cacador}.assalto_rastejante.on_fail{apply:envenenado}","modify:ability{enxame_simbiotico, classe:cacador}.investida_grudenta.on_fail{apply:caido}","trigger=ability{enxame_simbiotico, classe:cacador}.passo_do_enxame, instant{ca:+2, dex_save:+2}, duration:until_turn_start","check{atletismo, roll_add:+resource{dado_de_cacador}}","while_active{requires:target{chosen_enemies}, dadv:save{source(affected:ability{enxame_simbiotico, classe:cacador})}}"]},{"descricao":"*\"Na penumbra, tudo faz menos barulho — inclusive o erro. Ajusto o passo, corrijo o ângulo... e o que era falha vira acerto.\"*\n  Sua precisão torna-se letal quando você luta a partir das sombras.\n- **Correção de Mira:** Uma vez por turno, quando você errar uma jogada de ataque com arma, você pode rolar **1 Dado de Caçador** e somar o resultado à jogada de ataque original. Se o novo total igualar ou superar a **Classe de Armadura** do alvo, o ataque acerta.\n- **Corte que Ignora Couraça:** Enquanto você estiver em **Penumbra** ou **Escuridão** e atacar uma criatura que não possa ver você, seus ataques com arma ignoram **Resistência** a dano **Contundente**, **Cortante** e **Perfurante** não mágica. Imunidades não são afetadas.","id_classe_id":4,"id_habilidade":1053,"id_subclasse_id":117,"niveladquirido":10,"nome":"Golpe Cirúrgico","nome_ingles":null,"table_only":false,"tags_json":["trigger=miss, instant{roll_add:+resource{dado_de_cacador}}, 1/turn, weapon","while_active{requires:{in_dim_light and target{!can_see_self}}, weapon.ignore:resist:{concussao, cortante, perfurante}}"]},{"descricao":"*\"Depois de tanta mutação, a cabeça muda junto. O cheiro do sangue, o ritmo da respiração… tudo entrega. Agora, quando eu marco uma presa, não é só o corpo que sigo — é o erro dela tentando se esconder.\"*\n  Seus sentidos alterados permitem que você rastreie suas presas através de ilusões e disfarces.\n- **Localização Exata:** Enquanto uma criatura estiver afetada pela sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)** e no mesmo Plano de Existência que você, você sabe a localização exata dela. Você não sofre desvantagem ao atacar a criatura se ela estiver **Invisível** ou **Escondida**, embora você não veja sua aparência real, apenas sua posição no espaço.\n- **Interferência na Mudança de Forma:** Se a criatura marcada tentar se transformar ou mudar de forma (através de magias como Polimorfismo ou habilidades naturais) e essa tentativa exigir uma jogada de dados (como um teste de Carisma ou Inteligência), ela realiza a jogada com **Desvantagem**.\n- **Falha na Transformação:** Se a criatura falhar na rolagem mencionada acima, além de sofrer as consequências normais da falha, ela fica desorientada. Até o final do seu próximo turno, a criatura tem **Desvantagem** nas jogadas de ataque contra você e perde qualquer benefício de **Camuflagem** ou **Invisibilidade** contra seus sentidos.","id_classe_id":4,"id_habilidade":1054,"id_subclasse_id":112,"niveladquirido":10,"nome":"Percepção Predatória","nome_ingles":null,"table_only":false,"tags_json":["always_active{ requires:target{mark:ability{marca_do_cacador, classe:cacador}, same_plane}, suppress{dadv:attack{requires:target{invisivel}}} }","while_active{ requires:target{mark:ability{marca_do_cacador, classe:cacador}}, dadv:check{shapeshift(target)} }","trigger=fail_check{shapeshift(target)}, instant{ dadv:attack(target, against:self), restricts{hide, target} }, duration:until_turn_start"]},{"descricao":"*Eu não preciso esperar a oportunidade; eu construo ela. Todo monstro grande demais para encarar de frente me ensinou a mesma lição: nada é invencível, só mal-entendido, e por isso, quando marco um alvo, já não vejo um corpo, e sim um mapa de falhas esperando o golpe certo.*\n\nSua identificação e perseguição da presa se afinam:\n\n- **Vantagem Predatória.** Você tem Vantagem na primeira rolagem de ataque que fizer contra a sua Presa Marcada a cada turno.\n\n- **Marca Veloz.** Você não precisa mais usar uma Ação Bônus para usar Marca do Caçador. Em vez disso, ao usar a ação Atacar (Attack), você pode aplicar a Marca do Caçador a um alvo como parte de um dos seus ataques, antes ou depois da rolagem de ataque, à sua escolha.","id_classe_id":4,"id_habilidade":1055,"id_subclasse_id":null,"niveladquirido":11,"nome":"Predador Astuto","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Eu deixo de ser um vulto na mata e passo a ser a própria mata. Já tentei copiar truque de ladino, mas o que de fato resolveu foi aprender a ouvir o lugar antes de me mexer; hoje, quando quero sumir, nem eu mesmo consigo encontrar os meus rastros.*\n\nVocê se move como uma sombra na natureza. Você pode tomar a ação Esconder-se (Hide) como uma Ação Bônus, e não pode ser rastreado por meios não mágicos, a menos que você queira deixar rastro.","id_classe_id":4,"id_habilidade":1057,"id_subclasse_id":null,"niveladquirido":13,"nome":"Passos Invisíveis","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*\"Meu espírito não espera ordem. Quando o perigo chega perto demais, ele já está entre mim e a ameaça. Não é magia. É instinto. O dele e o meu, batendo juntos.\"*\n  O Espírito Primordial ganha a capacidade de intervir fisicamente para proteger seu mestre.\n- **Gatilho:** Uma criatura que o espírito possa ver atinge você com uma jogada de ataque enquanto o espírito estiver a até **9 metros [30 pés]** de você.\n- **Reação do Espírito:** O espírito usa sua **Reação** para absorver o impacto. O dano que você sofreria desse ataque é reduzido pela **metade**.\n- **Restrição:** O espírito não pode usar essa reação se estiver **Incapacitado**.","id_classe_id":4,"id_habilidade":1059,"id_subclasse_id":21,"niveladquirido":14,"nome":"Reflexo Instintivo","nome_ingles":null,"table_only":false,"tags_json":["action=reaction","trigger=hit_by_attack","requires:companion(range:30ft)","instant{dmg_reduction:half}","restriction{companion{incapacitado}}"]},{"descricao":"*\"Alguns monstros juram que me viram cair. Estão certos pela metade. Tem um instante, entre o último suspiro e a escuridão, em que algo me puxa de volta pelos dentes.\"*\n  Sua determinação em finalizar a caçada impede que você morra antes de sua presa.\n- **Quase-Morte Adiada:** Quando você for reduzido a **0 Pontos de Vida** e não morrer instantaneamente, você pode escolher cair para **1 Ponto de Vida** e permanecer consciente.\n- **Duração:** Este estado de resistência dura por **1 minuto** ou até você ser reduzido a **0 Pontos de Vida** novamente, o que ocorrer primeiro.\n- **Recuperação:** Uma vez que você use esta característica, você não pode usá-la novamente até terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1060,"id_subclasse_id":118,"niveladquirido":14,"nome":"Última Palavra","nome_ingles":null,"table_only":false,"tags_json":["trigger=drop_to_0","instant{ hp:=1 }","while_active{ requires:not{dead} }","duration:10","resource_cost:1/long_rest"]},{"descricao":"*\"Tem lugar que não se alcança com passo — só com fenda. Quando puxo o selo, o corpo afina, o peso some. Não é ficar invisível, é existir de lado.\"*\n  Você aprende a desfocar sua presença material, deslizando pelas dobras do espaço.\n- **Ativar o Véu:** No início do seu turno, se não estiver **Incapacitado**, você pode entrar em um estado semi-etéreo (sem exigir ação). Este efeito dura por um número de turnos igual ao seu modificador de **Sabedoria** ou **Inteligência** (mínimo de 1).\n- **Fantasmal:** Enquanto o efeito durar, você pode se mover através de outras criaturas e objetos como se fossem **Terreno Difícil**.\n- **Visão Etérea:** Você pode ver e interagir com criaturas no **Plano Etéreo** como se estivessem no Plano Material. O Mestre define a aparência visual dessas interações.\n- **Consequência Física:** Se você encerrar seu turno dentro de um objeto, você sofre **1d10** de dano de **Energia (Força)** e é expelido imediatamente para o espaço desocupado mais próximo. Você sofre dano de **Energia (Força)** adicional igual a **2** para cada **0,3 metro [1 pé]** que for deslocado dessa forma.\n- **Usos:** Você pode usar esta característica um número de vezes igual ao seu **Bônus de Proficiência**. Você recupera todos os usos gastos ao terminar um **Descanso Curto** ou **Descanso Longo**.","id_classe_id":4,"id_habilidade":1061,"id_subclasse_id":115,"niveladquirido":14,"nome":"Véu Desfeito","nome_ingles":null,"table_only":false,"tags_json":["action=free","trigger=turn_start","restriction{ incapacitado }","while_active{ move_through, sense:ethereal }","duration:max(1, spell_mod)","on:end{ if(in_object): dmg:1d10(forca), push:until_clear, dmg:+(2*ft_pushed)(forca) }","uses{pb, reset:short_rest}"]},{"descricao":"*\"Eles já não esperam meu comando — reagem comigo. Eu só aponto quem precisa ficar de pé, e centenas de corpos pequenos fazem o resto.\"*\n  Sua capacidade de proteção se estende aos seus aliados, transformando o enxame em um escudo móvel.\n- **Proteção Ampliada:** Você pode usar a **Resposta Instintiva** (Nível 6) quando qualquer criatura a até **9 metros [30 pés]** de você for alvo de um ataque ou estiver prestes a sofrer dano.\n- **Defesa contra Ataques:** Se o gatilho for um ataque, você impõe **Desvantagem** na jogada. Se o ataque ainda acertar, o alvo tem **Resistência** ao dano causado por esse ataque.\n- **Defesa contra Área:** Se o gatilho for um efeito que exige um Teste de Resistência para evitar dano, o alvo realiza o teste normalmente, mas ganha **Resistência** ao dano sofrido.\n- **Resgate Tático:** Ao usar a Resposta Instintiva, você pode mover a criatura protegida em até **9 metros [30 pés]** para um espaço desocupado. Esse movimento não provoca **Ataques de Oportunidade**.","id_classe_id":4,"id_habilidade":1062,"id_subclasse_id":116,"niveladquirido":14,"nome":"Colmeia Instintiva","nome_ingles":null,"table_only":false,"tags_json":["modify:ability{instinto_coletivo, classe:cacador}.target:creature(range:30ft)","trigger=hit_by_attack, instant{ source.dadv:attack, resist:source(requires:still_hit) }","trigger=save_roll(aoe), instant{resist:source}","instant{ push:30ft(target:guard) }"]},{"descricao":"*\"Um dia, eles não só cercaram meus passos — me ergueram. Não foi feitiço. Foi confiança: milhares de asas decidindo que, se eu precisava estar mais alto, eles me levariam.\"*\n  O enxame é denso o suficiente para erguer você do chão.\n- **Voo do Enxame:** Enquanto não estiver **Incapacitado**, você ganha **Deslocamento de Voo** igual ao seu Deslocamento de Caminhada.\n- **Queda Amortecida:** Se você cair ou for derrubado enquanto estiver voando, o enxame retarda sua descida. Você aterrissa suavemente no final do turno e não sofre **Dano de Queda**.","id_classe_id":4,"id_habilidade":1063,"id_subclasse_id":116,"niveladquirido":14,"nome":"Voo Simbiótico","nome_ingles":null,"table_only":false,"tags_json":["always_active{ move:fly(requires:not{condition{incapacitado, target:self}}) }","always_active{ dmg_reduction:all(take_damage{fall}, requires:move{fly}) }"]},{"descricao":"*\"O erro deles não é atacar. É atacar onde eu já não estou. O golpe corta o ar, encontra só breu — e, antes que percebam, a lâmina certa vem do lugar errado.\"*\n  Você usa as sombras para desviar golpes e punir a imprudência dos inimigos.\n- **Gatilho:** Uma criatura que você possa ver realiza uma jogada de ataque contra você.\n- **Sombras que Desviam:** Você pode usar sua **Reação** para impor **Desvantagem** nessa jogada de ataque. Você deve declarar o uso antes de saber se o ataque acertou ou errou.\n- **Golpe em Retorno:** Se o ataque errar você após o uso dessa reação, você pode realizar **1 Ataque com Arma** contra o atacante como parte da mesma reação. Se você estiver em **Penumbra** ou **Escuridão**, você tem **Vantagem** nessa jogada de ataque.","id_classe_id":4,"id_habilidade":1064,"id_subclasse_id":117,"niveladquirido":14,"nome":"Contra-Ataque Sombrio","nome_ingles":null,"table_only":false,"tags_json":["action=reaction","trigger=hit_by_attack","instant{ source.dadv:attack }","trigger=miss, instant{attack:weapon(target:source), adv:attack{requires:in_darkness}}"]},{"descricao":"*\"Já perdi a conta de quantas vezes mudei de corpo sem morrer. Se a mutação não serve mais, eu não aceito o erro — eu corrijo.\"*\n  Você aprende a purgar e reinjetar mutagênicos rapidamente no calor da batalha.\n- **Troca Rápida:** Como uma **Ação Bônus**, você pode encerrar imediatamente o efeito de 1 mutagênico ativo em seu corpo e, como parte da mesma ação, consumir um novo mutagênico que você tenha preparado.\n- **Regras:** O novo mutagênico ativa seus efeitos benéficos e colaterais normalmente. O mutagênico encerrado deixa de afetar você imediatamente.\n- **Usos:** Você pode usar esta característica um número de vezes igual ao seu modificador de **Sabedoria** ou **Inteligência** (mínimo de 1). Você recupera todos os usos gastos ao terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1065,"id_subclasse_id":112,"niveladquirido":14,"nome":"Transfusão Mutagênica","nome_ingles":null,"table_only":false,"tags_json":["action=bonus_action","instant{ end:defined{mutagenico_preparado}(target:self, pick:1), activate:defined{mutagenico_preparado}(target:self, pick:1) }","uses{max(1, spell_mod), reset:long_rest}"]},{"descricao":"*A caçada tomou minha mente por inteiro; já não sobra espaço para a vontade de outro. Ouvi voz demais tentando mandar em caçador — sussurro de entidade velha, promessa de demônio — e aprendi a não empurrar de volta: fico parado, calado, e deixo que ela se perca dentro de mim.*\n\nA obsessão da caça blinda sua mente. Você se torna imune à condição **Enfeitiçado** e a efeitos de possessão e dominação, e tem Vantagem em testes de resistência contra ficar **Amedrontado**.","id_classe_id":4,"id_habilidade":1066,"id_subclasse_id":null,"niveladquirido":15,"nome":"Vontade Inabalável","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Com o tempo, parei de depender só dos olhos; comecei a notar o jeito que o ar muda quando alguém respira fundo. Em campo aberto ou em caverna escura, quando eu chego já sei onde a presa está — não há mais ponto cego em que ela possa se esconder de mim.*\n\nSeus sentidos predatórios atingem o auge:\n\n- **Caçada Dupla.** Você pode manter duas Presas Marcadas simultaneamente. Aplicar uma nova Marca enquanto duas estão ativas substitui aquela à sua escolha.\n\n- **Visão às Cegas.** Você ganha **Visão às Cegas** com alcance de **9 metros [30 pés]**: dentro desse raio, você percebe a localização de tudo que não esteja atrás de cobertura total, mesmo estando **Cego** ou na escuridão, e enxerga criaturas **Invisíveis**.","id_classe_id":4,"id_habilidade":1068,"id_subclasse_id":null,"niveladquirido":17,"nome":"Instinto Predatório","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*\"Nenhum caçador sai ileso da trilha. Mas toda vez que achei que era o fim, senti algo responder lá no fundo. Com o ritual certo, ele volta. Não igual, nunca igual. Volta mais feroz, mais selvagem.\"*\n  Você aprende um **Segredo de Caçador** exclusivo desta ordem. Você pode gastar **3 Pontos de Segredo** e usar uma **Ação Bônus** para infundir seu espírito com fúria ancestral por **1 minuto**. O espírito deve estar presente e não dissipado. Enquanto o efeito durar, o espírito ganha os seguintes benefícios:\n- **Fúria da Natureza:** O espírito tem **Vantagem** em todas as jogadas de ataque.\n- **Potência Sobrenatural:** Os ataques do espírito causam **+1 Dado de Caçador** de dano extra. Além disso, os ataques dele ignoram **Resistência** a qualquer tipo de dano (mas não imunidade).\n- **Imortalidade Temporária:** A primeira vez que o espírito for reduzido a **0 Pontos de Vida** enquanto este efeito estiver ativo, ele não se dissipa. Em vez disso, ele retorna imediatamente a **1 Ponto de Vida**.\n- **Limitação:** Uma vez que você use este Segredo, você não pode usá-lo novamente até terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1070,"id_subclasse_id":21,"niveladquirido":18,"nome":"Segredo: Chamado da Presa Imortal","nome_ingles":null,"table_only":false,"tags_json":["action=bonus_action","resource_cost:pontos_de_segredo:3","while_active{ companion.adv:attack, companion.dmg:+resource{dado_de_cacador}, companion.ignore:resist, companion{trigger=drop_to_0, instant{hp:=1}, 1/long_rest} }","duration:10","resource_cost:1/long_rest"]},{"descricao":"*\"Mergulho a munição no óleo escuro, risco a runa que fecha caminhos — e, quando esse disparo encontra a presa, até a sombra dela entende que não tem mais para onde ir.\"*\n  Você aprende o **Segredo de Caçador** exclusivo chamado **Cilada Final**.\nAntes de realizar uma jogada de ataque contra uma criatura afetada pela sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)**, você pode gastar **3 Pontos de Segredo** para declarar a Cilada Final.\n- **Armadilha Espiritual:** Independente de o ataque acertar ou errar, a criatura é presa por uma magia antiga. Por **1 minuto**, ou até o fim do combate, a criatura sofre os seguintes efeitos:\n  - **Bloqueio Dimensional:** A criatura não pode se **teletransportar** ou utilizar [viagem planar](tbMagia, viagem-planar).\n  - **Sombra Fixada:** A criatura não pode se tornar **Invisível** nem entrar no **Plano Etéreo**.\n  - **Silêncio Mental:** A criatura não pode usar **Telepatia**.\n  - **Dreno Purgante:** No início de cada turno da criatura, ela sofre dano **Radiante** igual a **2 Dados de Caçador**.\n- **Limitação:** Você só pode manter uma Cilada Final ativa por vez. Aplicá-la em um novo alvo encerra o efeito no anterior.\n- **Recuperação:** Após usar este Segredo, você não pode usá-lo novamente até terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1071,"id_subclasse_id":118,"niveladquirido":18,"nome":"Segredo: Cilada Final","nome_ingles":null,"table_only":false,"tags_json":["trigger=next_attack, requires:target{mark:ability{marca_do_cacador, classe:cacador}}","resource_cost:pontos_de_segredo:3","instant{ restricts{teleport, condition{invisivel}, telepathy, target:target} }","trigger=turn_start, instant{ dmg:2(resource{dado_de_cacador})(radiante) }","duration:10","max:1","resource_cost:1/long_rest"]},{"descricao":"*\"Depois de ver portais rasgarem vilas e monstros cruzarem fendas que nunca deveriam existir, eu entendi: alguém precisava aprender a ir e voltar por esses lugares sem se perder.\"*\n  Você adquire o **Segredo de Caçador** conhecido como Caminho Final. Este segredo não conta no limite de segredos que você pode conhecer.\n- **Lista de Travessias:** Você aprende a conjurar as seguintes magias:\n  - [Portal Arcano](tbMagia, portal-arcano) **[Arcane Gate]**\n  - Palavra de Recordação **[Word of Recall]**\n  - Etereidade **[Etherealness]**\n  - Mansão Magnífica de Mordenkainen **[Mordenkainen’s Magnificent Mansion]**\n  - Teletransporte **[Teleport]**\n  - [Viagem Planar](tbMagia, viagem-planar) **[Plane Shift]**\n- **Preparação:** Ao terminar um **Descanso Longo**, você pode preparar até **2 magias** dessa lista. Uma vez que você conjure uma magia preparada desta forma, você não pode conjurá-la novamente através deste Segredo até prepará-la de novo.\nPara conjurar uma dessas magias preparadas, você deve gastar **3 Pontos de Segredo**. Você não gasta espaços de magia nem componentes materiais.\n- **Atributo de [Conjuração](tbClassehabilidade, cacador, conjuracao):** Use seu modificador de **Sabedoria** ou **Inteligência** para definir a CD e jogadas de ataque dessas magias.\n- **Maestria de Pergaminhos:** Você pode usar **Pergaminhos de Magia** contendo qualquer uma das magias da lista acima sem necessidade de testes, independente da sua lista de magias de classe.","id_classe_id":4,"id_habilidade":1072,"id_subclasse_id":115,"niveladquirido":18,"nome":"Segredo: Caminho Final","nome_ingles":null,"table_only":false,"tags_json":["spell_selection:fonte:caminho_final{ extra, fora_do_limite, list:[portal-arcano, palavra-de-retorno, etereidade, magnifica-mansao, teletransporte, viagem-planar] }","pick:caminho_final_preparada:2","reset:long_rest","cast{spell:caminho_final_preparada, modifiers{spell_mod, without{slot}, without{material}}}","resource_cost:pontos_de_segredo:3"]},{"descricao":"*\"Minha lâmina só abriu caminho. O que matou veio depois. Quando o aço cortou, o enxame entrou — escondido em carne, veia e sombra, comendo por dentro.\"*\n  Você adquire o **Segredo de Caçador** conhecido como Ninho Devorador.\nQuando você acertar um ataque contra uma criatura afetada pela sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)**, você pode gastar **3 Pontos de Segredo** para ativar este efeito (sem necessidade de ação).\n- **Infestação:** O alvo deve realizar um Teste de Resistência de **Constituição** contra sua **CD de [Segredos de Caçador](tbClassehabilidade, cacador, segredos-de-cacador)**.\n  - **Falha:** Um enxame devorador infesta o alvo por **1 minuto**. A criatura não pode recuperar **Pontos de Vida** e, no início de cada turno dela, sofre **4 Dados de Caçador** de dano **Necrótico**.\n  - **Sucesso:** O alvo sofre dano **Necrótico** imediato igual a **2 Dados de Caçador** e o efeito termina.\n- **Propagação:** Se uma criatura morrer enquanto estiver infestada pelo Ninho Devorador, você pode escolher uma nova criatura hostil a até **27 metros [90 pés]** do cadáver. O enxame salta para o novo alvo, aplicando automaticamente sua **[Marca do Caçador](tbClassehabilidade, cacador, marca-do-cacador)** nele (sem custo). O novo alvo deve fazer o Teste de Resistência de Constituição imediatamente para evitar ser infestado.\n- **Limitação:** Você só pode ter **1 Ninho Devorador** ativo por vez.","id_classe_id":4,"id_habilidade":1073,"id_subclasse_id":116,"niveladquirido":18,"nome":"Segredo: Ninho Devorador","nome_ingles":null,"table_only":false,"tags_json":["trigger=hit, requires:target{mark:ability{marca_do_cacador, classe:cacador}}","resource_cost:pontos_de_segredo:3","instant{ save{con, cd=ability{segredos_de_cacador, classe:cacador}.cd} }","on_fail:{ restricts{heal, target}, trigger=turn_start, instant{dmg:4(resource{dado_de_cacador})(necrotico)}, duration:10 }","on_success:{ dmg:2(resource{dado_de_cacador})(necrotico) }","trigger=reduce_to_0, instant{ apply:ability{marca_do_cacador, classe:cacador}(target:enemies(range:90ft), without{cost}), save{con, cd=ability{segredos_de_cacador, classe:cacador}.cd} }","max:1"]},{"descricao":"*\"Puxei o selo de fumaça e deixei cair no chão. A névoa subiu pesada, como se o próprio ar tivesse lembrado dos mortos. Lá dentro, passo e lâmina viram sussurro.\"*\n  Você aprende o **Segredo de Caçador** conhecido como Névoa Sepulcral.\nComo uma **Ação**, você gasta **3 Pontos de Segredo** para criar uma esfera de escuridão mágica com **9 metros [30 pés]** de raio, centrada em você. Essa névoa dura por **1 minuto** ou até ser dissipada com uma **Ação Bônus**.\n- **Escuridão Absoluta:** A névoa bloqueia luz natural e dissipa magias de luz de **6º Círculo** ou inferior. Criaturas dentro da área que não possuam a capacidade de ver em **Escuridão Mágica** sofrem a condição **Cego**.\n- **Passo entre Lâminas:** Enquanto estiver na névoa, você pode usar uma **Ação Bônus** para se teletransportar para um espaço desocupado dentro da área. Não é necessário ter linha de visão.\n- **Golpe e Desapareço:** Sempre que você realizar um ataque contra uma criatura dentro da névoa, você pode se teletransportar para um espaço desocupado na área (antes ou depois do ataque) sem gastar movimento e sem provocar **Ataques de Oportunidade**.\n- **Recuperação:** Após usar este Segredo, você não pode usá-lo novamente até terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1074,"id_subclasse_id":117,"niveladquirido":18,"nome":"Segredo: Névoa Sepulcral","nome_ingles":null,"table_only":false,"tags_json":["action=action","resource_cost:pontos_de_segredo:3","aura{ radius:30ft, target:enemies, effects{ apply:cego(restriction{sense:devilsight}) } }","duration:10","while_active{action:bonus_action, instant{teleport:30ft(without{los})}}","trigger=attack_roll(target:enemies(in_aura)), instant{teleport:30ft(without{aoo})}","resource_cost:1/long_rest"]},{"descricao":"*\"Dizem que meu corpo está contaminado. Estão certos. Só esquecem um detalhe: a toxina não é problema meu. É deles.\"*\n  Você adquire o **Segredo de Caçador** conhecido como Sangue Venenoso.\n- **Gatilho:** Quando você realizar a ação **Atacar** (corpo a corpo ou desarmado), você pode gastar **3 Pontos de Segredo** para ativar este efeito antes ou depois da jogada de ataque. A ativação ocorre independente de o ataque acertar ou errar.\n- **Pulso Tóxico:** Criaturas à sua escolha num raio de **3 metros [10 pés]** de você devem realizar um Teste de Resistência de **Constituição** contra sua **CD de [Segredos de Caçador](tbClassehabilidade, cacador, segredos-de-cacador)**.\n  - **Falha:** A criatura sofre **6 Dados de Caçador** de dano **Ácido** e fica **Cega** e **Atordoada** por **1 minuto**. Enquanto estiver sob esse efeito, o deslocamento dela é reduzido pela **metade**.\n  - **Sucesso:** A criatura sofre metade do dano e não sofre nenhuma condição ou redução de deslocamento.\n- **Resistência Contínua:** Uma criatura afetada pode repetir o Teste de Resistência sempre que sofrer dano. Em um sucesso, todos os efeitos terminam para ela.\n- **Recuperação:** Após usar este Segredo, você não pode usá-lo novamente até terminar um **Descanso Longo**.","id_classe_id":4,"id_habilidade":1075,"id_subclasse_id":112,"niveladquirido":18,"nome":"Segredo: Sangue Venenoso","nome_ingles":null,"table_only":false,"tags_json":["trigger=action{attack:{melee | unarmed}}","resource_cost:pontos_de_segredo:3","instant{ aoe{ radius:10ft, target:enemies, save{con, cd=ability{segredos_de_cacador, classe:cacador}.cd}, dmg:6(resource{dado_de_cacador})(acido), on_success:half } }","on_fail:{ apply:cego, apply:atordoado, speed:half, repeat_save:take_damage }","duration:10","resource_cost:1/long_rest"]},{"descricao":"*Caçar nunca foi só encontrar a presa; é aceitar que ela já estava morta desde o instante em que eu a escolhi. As presas não lutam contra mim: tentam escapar de um fim que já está escrito. Anoto a última página sem pressa, porque sou eu o ponto final da trilha.*\n\nA caça se torna uma extensão do seu próprio modo de existir. Os benefícios abaixo se aplicam contra qualquer criatura Marcada por você ou afetada por qualquer Segredo do Caçador, seja por armadilhas, venenos, sinais ou outra técnica:\n\n- **Pressão Constante.** Você tem Vantagem em rolagens de ataque contra essas criaturas, e elas têm Desvantagem em rolagens de ataque contra você.\n\n- **Terceiro Golpe Certeiro.** Ao usar a ação Atacar (Attack) contra uma dessas criaturas, você pode fazer três ataques em vez de dois, uma vez por turno.\n\n- **Instinto Acima de Tudo.** Você tem Vantagem em qualquer teste de habilidade ou de resistência que essas criaturas forcem você a fazer.","id_classe_id":4,"id_habilidade":1077,"id_subclasse_id":null,"niveladquirido":20,"nome":"Domínio da Caçada","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A natureza não me ensinou apenas a convocar uma fera; ensinou a protegê-la, alimentá-la com fogo e partilhar com ela cada defesa. Nossas magias seguem o mesmo pacto: nenhuma força recebida por um de nós precisa permanecer apenas com ele.*\n\nVocê tem sempre preparadas as magias da tabela a seguir. Elas contam como magias de Caçador para você e não contam no seu limite de magias preparadas.\n\n| Nível de Caçador | Magias |\n| --- | --- |\n| 3º | Amizade Animal [Animal Friendship]\nAbsorver Elementos [Absorb Elements] |\n| 5º | Sopro de Dragão [Dragon''s Breath]\nVínculo Protetor [Warding Bond] |\n| 9º | Conjurar Animais [Conjure Animals]\nProteção contra Energia [Protection from Energy] |\n| 13º | Dominar Fera [Dominate Beast]\nEscudo de Fogo [Fire Shield] |\n| 17º | Comunhão com a Natureza [Commune with Nature]\nDespertar [Awaken] |\n\nAlém dessas magias, a Linha Mestra da sua Ordem é a Linha **Armadilhas e Emboscadas**: você conhece todos os Segredos dessa Linha cujo Grau tenha desbloqueado, e eles não contam no seu limite de Segredos preparados.","id_classe_id":4,"id_habilidade":1078,"id_subclasse_id":152,"niveladquirido":3,"nome":"Magias e Segredos da Ordem da Aliança Selvagem","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*O pacto está selado. A forma pode mudar, mas a lealdade é absoluta. Ele é a minha sombra armada de presas, garras, escamas ou asas. Não o domei; nós nos reconhecemos e decidimos que, daquela noite em diante, caçaríamos juntos.*\n\nVocê aprende a magia Familiar de Batalha [Battle Familiar]. Ela conta como uma magia de Caçador para você, está sempre preparada e não conta no seu limite de magias preparadas.\n\nSeu Familiar de Batalha é um Espírito Primordial e recebe os benefícios a seguir:\n\n- **Invocação Primordial.** Quando adquire esta característica e sempre que termina um Descanso Longo, você pode conjurar Familiar de Batalha sem gastar espaço de magia, fornecer componentes ou usar uma ação. Você também pode realizar um ritual de 1 minuto e gastar 1 Ponto de Segredo para conjurá-la novamente. Conjurada dessa forma, a magia dura até o espírito cair a 0 Pontos de Vida, você conjurá-la novamente, você morrer ou decidir dispensá-lo; ela não termina após 1 hora.\n\n- **Círculo Primordial.** Para determinar os efeitos de Familiar de Batalha, o Círculo da magia é igual ao maior Círculo de espaço de magia concedido pela tabela do Caçador, com um mínimo de 2º Círculo. Espaços de magia recebidos de outras classes não aumentam esse Círculo.\n\n- **Forma Livre.** O espírito pode assumir a aparência de qualquer animal, dragão, criatura fantástica ou combinação de criaturas à sua escolha. Escolha também o tipo dele entre Celestial, Dragão, Fera, Feérico ou Ínfero. A aparência e o tipo não alteram as estatísticas do familiar por si mesmos.\n\n- **Vínculo Primordial.** O espírito adiciona dez vezes o seu nível de Caçador ao máximo de Pontos de Vida dele e o seu Bônus de Proficiência à Classe de Armadura, aos testes de habilidade e aos testes de resistência dele. O espírito também recebe os benefícios do seu Inimigo Favorito.\n\n- **Elo Mental.** Você e o espírito podem se comunicar telepaticamente enquanto estiverem no mesmo plano de existência.\n\n- **Comando.** Uma vez em cada um dos seus turnos, você pode usar uma Ação Bônus para ordenar que o espírito realize imediatamente uma Ação ou Ação Bônus disponível no bloco de estatísticas dele. O espírito gasta a Reação para obedecer e só pode realizar um ataque como parte dessa Reação.\n\n- **Vida e Morte.** Quando o espírito cai a 0 Pontos de Vida, ele se dissipa e deixa para trás qualquer objeto que estivesse vestindo ou carregando. Ele retorna com todos os Pontos de Vida quando você conjura Familiar de Batalha novamente por Invocação Primordial.","id_classe_id":4,"id_habilidade":1079,"id_subclasse_id":152,"niveladquirido":3,"nome":"Companheiro Primordial","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A forma dele nunca permanece igual por muito tempo. Cada nova invocação traz outra resposta da natureza: sentidos mais aguçados, couro resistente, asas, veneno ou fogo. Escolho o que a próxima trilha exige, e o espírito desperta preparado para percorrê-la comigo.*\n\nSempre que conjura Familiar de Batalha por Companheiro Primordial, escolha as Evoluções Totêmicas manifestadas pelo espírito. Você escolhe uma evolução no 3º nível e uma evolução adicional no 6º, 10º, 14º e 18º nível de Caçador. As escolhas permanecem enquanto aquela conjuração estiver ativa e podem ser alteradas na próxima vez que você conjurar o espírito.\n\n**Evoluções Totêmicas.**\n\n- **Audição e Faro Aguçados.** O espírito tem Vantagem em testes de Sabedoria (Percepção) baseados em audição ou olfato.\n\n- **Camuflagem Natural.** O espírito tem Vantagem em testes de Destreza (Furtividade) realizados em terreno natural, Penumbra ou Escuridão.\n\n- **Escalada Aracnídea.** O espírito recebe deslocamento de escalada igual ao deslocamento de caminhada e pode se mover por paredes e tetos sem realizar testes de habilidade.\n\n- **Fôlego Prolongado.** O espírito pode prender a respiração por 1 hora.\n\n- **Anfíbio.** O espírito pode respirar ar e água.\n\n- **Resistência Elemental.** Escolha ácido, elétrico, fogo, frio ou trovejante. O espírito recebe Resistência ao tipo escolhido. Você pode selecionar esta evolução mais de uma vez, escolhendo um tipo diferente em cada seleção.\n\n- **Táticas de Matilha.** O espírito tem Vantagem nas jogadas de ataque contra uma criatura se ao menos um aliado dele estiver a até 1,5 metro [5 pés] da criatura e não estiver Incapacitado.\n\n- **Alcance Estendido.** O alcance dos ataques corpo a corpo do espírito aumenta em 1,5 metro [5 pés].\n\n- **Ecolocalização.** O espírito recebe Visão às Cegas de 9 metros [30 pés]. Ele perde essa visão enquanto estiver Surdo.\n\n- **Investida.** Se o espírito se mover ao menos 6 metros [20 pés] em linha reta em direção a um alvo e acertá-lo com Retalhar [Rend] no mesmo turno, o ataque causa dano adicional igual a uma rolagem do seu Dado de Caçador. O alvo deve ser bem-sucedido em um teste de resistência de Força contra a sua CD de Magia ou fica Caído.\n\n- **Sopro Primordial.** Escolha ácido, elétrico, fogo, frio, trovejante ou veneno. Uma vez por turno, quando o espírito usaria Retalhar [Rend], ele pode substituir esse ataque por um sopro num Cone de 4,5 metros [15 pés]. Cada criatura na área realiza um teste de resistência de Destreza contra a sua CD de Magia, sofrendo um número de rolagens do seu Dado de Caçador igual ao maior entre os seus modificadores de Inteligência e Sabedoria (mínimo de uma rolagem) em uma falha, ou metade em um sucesso. O dano é do tipo escolhido.","id_classe_id":4,"id_habilidade":1080,"id_subclasse_id":152,"niveladquirido":3,"nome":"Evolução Totêmica","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Aprendi a vestir a hora incerta como quem veste uma capa. Meus feitiços são de disfarce, névoa e medo, colhidos no instante entre o dia e a noite — magia que não ilumina nada, mas que faz a presa duvidar dos próprios olhos até eu já estar em cima dela.*\n\nVocê tem sempre preparadas as magias a seguir; elas contam como magias de Caçador para você e não contam no seu limite de magias preparadas.\n\n| Nível de Caçador | Magias |\n| --- | --- |\n| 3º | Disfarçar-se [Disguise Self]\nNévoa Obscurecente [Fog Cloud] |\n| 5º | Escuridão [Darkness]\nTruque da Corda [Rope Trick] |\n| 9º | Medo [Fear]\nIndetectabilidade [Nondetection] |\n| 13º | Mortalha de Sombras [Shadow of Moil]\nPorta Dimensional [Dimension Door] |\n| 17º | Modificar Memória [Modify Memory]\nAparência [Seeming] |\n\nAlém das magias acima, a Linha Mestra da sua Ordem é a Linha **Armadilhas e Emboscadas**: você tem sempre preparados todos os Segredos dessa Linha, adquirindo cada um assim que alcança o nível de pré-requisito do Grau correspondente, e eles não contam no seu limite de Segredos preparados.","id_classe_id":4,"id_habilidade":1081,"id_subclasse_id":153,"niveladquirido":3,"nome":"Magias e Segredos da Ordem do Crepúsculo","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Não corro para chegar depois. Já estou lá quando o resto decide que é hora de lutar — no primeiro olhar na direção errada, na primeira sombra que se estica.*\n\nAs trevas não escondem nada de você. Você ganha Visão no Escuro de **18 metros [60 pés]**; se já possuir Visão no Escuro, o alcance dela aumenta em **18 metros [60 pés]**. Além disso, você enxerga normalmente através de escuridão, seja ela mágica ou não mágica.\n\nVocê também aprendeu a golpear no instante exato. Sempre que faz uma Jogada de Iniciativa, você adiciona o seu modificador de Inteligência ou Sabedoria ao resultado (mínimo de **+1**). E, no seu primeiro turno de cada combate, se você usa a ação Atacar, pode fazer um ataque adicional com arma como parte da mesma ação; se esse ataque adicional acertar, causa dano extra igual ao seu nível de Caçador, do mesmo tipo da arma.","id_classe_id":4,"id_habilidade":1082,"id_subclasse_id":153,"niveladquirido":3,"nome":"Caçador das Sombras","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Selo a presa com um fio de trevas, e a partir dali ela caça às cegas — e eu, não. Roubo dela a vantagem dos olhos afiados e da visão que atravessa o escuro, de modo que, na penumbra, sou apenas um vazio de onde os golpes chegam sem aviso.*\n\nAo aplicar a sua Marca do Caçador, você embota os sentidos da presa contra você. Enquanto uma criatura estiver sob a sua Marca, ela não pode se beneficiar de Visão no Escuro, Visão Verdadeira nem de visão no escuro mágica para enxergar você. Além disso, enquanto você estiver em Penumbra ou Escuridão, você é considerado **Invisível** para as criaturas Marcadas.","id_classe_id":4,"id_habilidade":1083,"id_subclasse_id":153,"niveladquirido":3,"nome":"Marca do Crepúsculo","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A fera fere; o caçador também sara. Aprendi a costurar a própria carne tão depressa quanto a rasgo, e por isso os meus feitiços são de cura, vigor e restauração — porque quem solta um monstro por dentro precisa saber, antes de tudo, como remendar o que ele destrói.*\n\nVocê tem sempre preparadas as magias a seguir; elas contam como magias de Caçador para você e não contam no seu limite de magias preparadas.\n\n| Nível de Caçador | Magias |\n| --- | --- |\n| 3º | Comunhão Ancestral [Ancestral Communion]\nGolpe Iracundo [Wrathful Smite] |\n| 5º | Alterar-se [Alter Self]\nSentidos Animais [Beast Sense] |\n| 9º | Corcel Fantasma [Phantom Steed]\nPressa [Haste] |\n| 13º | Dominar Fera [Dominate Beast]\nChamado da Natureza [Call of the Wild] |\n| 17º | Golpe do Vento de Aço [Steel Wind Strike]\nDespertar [Awaken] |\n\nAlém das magias acima, a Linha Mestra da sua Ordem é a Linha **Alquimia e Poções**: você tem sempre preparados todos os Segredos dessa Linha, adquirindo cada um assim que alcança o nível de pré-requisito do Grau correspondente, e eles não contam no seu limite de Segredos preparados.","id_classe_id":4,"id_habilidade":1084,"id_subclasse_id":154,"niveladquirido":3,"nome":"Magias e Segredos da Ordem do Despertar","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Senti os dentes crescerem primeiro, depois o resto veio junto; por um instante o mundo ficou maior, mais nítido, mais simples. Caçar. Só isso. Quando solto a coleira, não é a fera que me domina — sou eu que escolho, por um tempo, olhar o mundo com os olhos dela.*\n\nVocê aprendeu a despertar a fera adormecida em você sob seus próprios termos. Como uma **Ação Bônus**, você assume uma forma híbrida e monstruosa por até 1 hora. Você reverte à sua forma normal como uma **Ação Bônus**, e reverte automaticamente se cair inconsciente ou morrer. Você pode fazer isso **uma vez**, recuperando o uso ao terminar um Descanso Curto ou Descanso Longo. Enquanto estiver transformado, você se beneficia das seguintes características:\n\n**Pele Resiliente.** Você tem Resistência a dano concussivo, perfurante e cortante, seja de ataques mágicos ou não mágicos. Além disso, enquanto não estiver usando armadura pesada nem empunhando um escudo, você recebe **+1** na Classe de Armadura.\n\n**Força Feral.** Você tem Vantagem em testes e testes de resistência de Força, e recebe **+1** no dano dos seus ataques corpo a corpo. Esse bônus de dano aumenta para +2 no 11º nível de Caçador e para +3 no 18º nível.\n\n**Golpes Predatórios.** As suas presas e garras tornam-se armas mortais. Enquanto não estiver empunhando um escudo, os seus Golpes Desarmados causam **uma rolagem do seu Dado de Caçador** de dano concussivo ou cortante (à sua escolha) e podem usar Destreza, em vez de Força, nas jogadas de ataque e dano. Como uma **Ação Bônus**, você pode fazer um Golpe Desarmado; se o alvo estiver sob a sua Marca do Caçador, você faz **dois** Golpes Desarmados em vez de um.\n\n**Uivo do Despertar.** Como uma **Ação Bônus**, você gasta **2 Pontos de Segredo** e solta um uivo sobrenatural. Cada criatura à sua escolha num raio de **4,5 metros [15 pés]** de você faz um teste de resistência de Sabedoria contra a sua CD de Magia ou fica com **Desvantagem** em jogadas de ataque e em testes de resistência até o início do seu próximo turno. Você pode soltar o Uivo do Despertar no instante em que assume a Forma Desperta, como parte da mesma **Ação Bônus** da transformação; feito dessa maneira, ele não custa Pontos de Segredo.","id_classe_id":4,"id_habilidade":1085,"id_subclasse_id":154,"niveladquirido":3,"nome":"Forma Desperta","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Enquanto a presa respira, a fome não me solta e não me deixa cansar. A coleira só aperta de novo quando o coração dela para. É a caçada que sustenta a fera acordada dentro de mim: enquanto houver algo marcado para abater, o monstro não recua, e eu tampouco recuo com ele.*\n\nA fome que dorme em você só descansa quando a caçada termina. Enquanto houver uma criatura sob a sua Marca do Caçador, a sua Forma Desperta não conta o tempo de duração: ela não expira por conta própria e dura enquanto você quiser, sem que a hora limite se esgote. Além disso, quando uma criatura sob a sua Marca morre, a fera se sacia por um instante e você recupera um uso gasto da Forma Desperta.","id_classe_id":4,"id_habilidade":1086,"id_subclasse_id":154,"niveladquirido":3,"nome":"Marca da Caçada Faminta","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Aprendi a sussurrar na língua das asas e a espalhar o enxame como névoa, teia ou praga. Cada magia dá uma forma diferente à colônia, permitindo que milhares de corpos pequenos ocupem o espaço onde uma única lâmina jamais bastaria.*\n\nVocê tem sempre preparadas as magias a seguir; elas contam como magias de Caçador e não contam no seu limite de magias preparadas.\n\n| Nível de Caçador | Magias |\n| --- | --- |\n| 3º | Fadafogo [Faerie Fire]\nNévoa Obscurecente [Fog Cloud] |\n| 5º | Teia [Web]\nPasso Brumoso [Misty Step] |\n| 9º | Forma Gasosa [Gaseous Form]\nEscudo Cacofônico [Cacophonic Shield] |\n| 13º | Olho Arcano [Arcane Eye]\nConfusão [Confusion] |\n| 17º | Praga de Insetos [Insect Plague]\nVínculo Telepático de Rary [Rary''s Telepathic Bond] |\n\nAlém das magias acima, a Linha Mestra da sua Ordem é a Linha **Alquimia e Poções**: você tem sempre preparados todos os Segredos dessa Linha, adquirindo cada um assim que alcança o nível de pré-requisito do Grau correspondente, e eles não contam no seu limite de Segredos preparados.","id_classe_id":4,"id_habilidade":1087,"id_subclasse_id":155,"niveladquirido":3,"nome":"Magias e Segredos da Ordem do Enxame","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Eles dormem nas dobras da roupa, sob a pele e entre as tiras de couro, nunca como parasitas, mas como sentinelas. Quando acerto a presa e dou o sinal, o chão se move, o ar escurece e a colônia termina o golpe.*\n\nVocê abriga um enxame de espíritos da natureza ou criaturas Minúsculas, como insetos, roedores ou aves. O enxame ocupa o seu espaço, move-se com você e permanece intangível para outras criaturas até ser comandado.\n\nUma vez em cada um dos seus turnos, imediatamente depois de acertar uma criatura com uma jogada de ataque, você pode comandar o enxame. O ataque causa dano adicional igual a uma rolagem do seu Dado de Caçador, e você escolhe um dos efeitos a seguir:\n\n- **Enxame Enfraquecedor.** O alvo tem Desvantagem na próxima jogada de ataque que realizar antes do início do seu próximo turno. Se esse ataque ainda acertar, ele reduz o dano causado em uma quantidade igual a uma rolagem do seu Dado de Caçador.\n\n- **Força dos Muitos.** O alvo deve ser bem-sucedido em um teste de resistência de Força contra a sua CD de Magia ou é empurrado 4,5 metros [15 pés].\n\n- **Passo da Colônia.** Você se move horizontalmente até 1,5 metro [5 pés] para um espaço desocupado. Esse movimento não provoca Ataques de Oportunidade.\n\n- **Subjugação da Horda.** O alvo deve ser bem-sucedido em um teste de resistência de Força contra a sua CD de Magia. Em uma falha, o deslocamento dele é reduzido à metade e ele não pode realizar Ataques de Oportunidade até o início do seu próximo turno.","id_classe_id":4,"id_habilidade":1088,"id_subclasse_id":155,"niveladquirido":3,"nome":"Enxame Simbiótico","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Com o tempo, deixei de pensar neles como meu enxame e passei a pensar em nós. Se escalo, milhares de patas encontram apoio; se descanso, centenas de olhos permanecem abertos; se estendo a mão, a colônia alcança primeiro.*\n\nSeu corpo e o enxame passam a operar por meio de uma consciência compartilhada, concedendo os benefícios a seguir:\n\n- **Enxame Arcano.** Você aprende o truque Mãos Mágicas [Mage Hand]. Ele conta como uma magia de Caçador para você e, quando o conjura, a mão assume a forma de uma porção do enxame.\n\n- **Sentidos Coletivos.** Você não pode ser Surpreendido enquanto não estiver Inconsciente.\n\n- **Escalada Orgânica.** Você ganha deslocamento de escalada igual ao seu deslocamento de caminhada. Pode atravessar superfícies verticais e tetos sem realizar testes de habilidade, desde que tenha ao menos uma mão livre.\n\n- **Queda Amortecida.** Você está sempre sob o efeito da magia Queda Suave [Feather Fall], sem precisar conjurá-la ou manter Concentração.","id_classe_id":4,"id_habilidade":1089,"id_subclasse_id":155,"niveladquirido":3,"nome":"Simbiose do Enxame","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Sussurre o nome certo, e até o túmulo escuta. Meus feitiços detectam o mal, silenciam a cripta, falam com os mortos e banem o que não pertence a este lado — palavras de ofício que Cessira ensinou aos que aceitaram vigiar a fronteira entre os vivos e os que já morreram.*\n\nVocê tem sempre preparadas as magias a seguir; elas contam como magias de Caçador para você e não contam no seu limite de magias preparadas.\n\n| Nível de Caçador | Magias |\n| --- | --- |\n| 3º | Detectar Mal e Bem [Detect Evil and Good]\nProteção contra o Mal e o Bem [Protection from Evil and Good] |\n| 5º | Silêncio [Silence]\nVer Invisíveis [See Invisibility] |\n| 9º | Remover Maldição [Remove Curse]\nCorcel Fantasmagórico [Phantom Steed] |\n| 13º | Banimento [Banishment]\nAssassino Fantasmagórico [Phantasmal Killer] |\n| 17º | Solo Sepulcral [Grave Ground]\nDissipar o Mal e o Bem [Dispel Evil and Good] |\n\nAlém das magias acima, a Linha Mestra da sua Ordem é a Linha **Conhecimentos Ancestrais (Sinais)**: você tem sempre preparados todos os Segredos dessa Linha, adquirindo cada um assim que alcança o nível de pré-requisito do Grau correspondente, e eles não contam no seu limite de Segredos preparados.","id_classe_id":4,"id_habilidade":1090,"id_subclasse_id":156,"niveladquirido":3,"nome":"Magias e Segredos da Ordem dos Exorcistas","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Acendo a lanterna não para enxergar, mas para que eles saibam que eu enxergo. A minha luz revela o que rasteja invisível, cospe fogo sobre os mortos e reencena o último suspiro de um cadáver — é distintivo, arma e testemunha, tudo forjado no mesmo vidro consagrado.*\n\nVocê porta a sua Lanterna do Véu, o implemento sagrado que é a marca do seu ofício — assim chamada qualquer que seja a forma que ela assuma. Você ganha proficiência com Ferramentas de Exorcista e usa a lanterna como um foco de conjuração para as suas magias de Caçador. Mais que isso, você canaliza os seus **Segredos do Caçador** através dela: não precisa carregar os reagentes, as ferramentas e os focos que eles exigiriam, pois a lanterna os manifesta em formas espectrais no instante em que você os usa.\n\nAssim, uma Granada de Luz floresce como uma esfera de luz fria erguida pela chama da lanterna; uma Rede de Enrosco Rápido tece-se no ar em fios fantasmagóricos; um Sinal arde diante de você como um glifo de fogo azul. O efeito mecânico dos seus Segredos não muda — apenas a forma com que se manifestam.\n\nComo uma **Ação Bônus**, você ajusta a lanterna para que ela ilumine intensamente um raio de **1,5 a 6 metros [5 a 20 pés]** e fracamente o dobro dessa distância, ou para apagá-la por completo. Enquanto a segura, você pode usar uma **Ação** e uma palavra de comando: se houver mortos-vivos a até **18 metros [60 pés]** de você que não estejam sob cobertura total, a chama pisca em vermelho antes de voltar ao seu brilho. E, tocando a lanterna a um cadáver Grande ou menor, você faz surgir uma imagem espectral azulada que reencena em silêncio os últimos 6 segundos da vida consciente da criatura — apenas as ações dela, não a causa. Isso não afeta mortos-vivos, e cada cadáver só pode ser revelado uma vez.\n\nVocê determina a forma da sua lanterna rolando na tabela a seguir ou escolhendo uma. Se a perder, pode realizar uma cerimônia de 1 hora durante um Descanso Curto ou Longo para criar magicamente uma substituta, o que destrói a anterior.\n\n| 1d6 | Forma da Lanterna do Véu |\n| --- | --- |\n| 1 | Uma lanterna de furta-fogo de ferro enegrecido, com o vidro defumado. |\n| 2 | Um turíbulo de bronze que balança preso a correntes, exalando fumaça de incenso. |\n| 3 | Um crânio polido, com uma chama fria ardendo nas órbitas. |\n| 4 | Um relicário de prata guardando um fragmento de osso que brilha por dentro. |\n| 5 | Uma vela votiva grossa sobre um castiçal retorcido, cuja chama nunca se apaga. |\n| 6 | Um fogo-fátuo aprisionado dentro de um frasco de vidro grosso. |","id_classe_id":4,"id_habilidade":1091,"id_subclasse_id":156,"niveladquirido":3,"nome":"Lanterna do Véu","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Selada a presa, não há regaço, nem sombra, nem fuga — só a conta a pagar. Prendo a criatura ao limiar entre os mundos, e a partir dali ela não escorrega para o Etéreo nem se esconde na invisibilidade; carrega a minha marca como quem carrega a própria sentença.*\n\nAo aplicar a Marca do Caçador, você escolhe **radiante** ou **frio**: o dano da sua Marca passa a ser desse tipo enquanto ela durar. Você sempre sabe se a criatura Marcada está **Sangrando**, e quando você lhe causa o dano da Marca enquanto ela está Sangrando, ela sofre dano adicional igual ao seu **Bônus de Proficiência**, do mesmo tipo escolhido.\n\nAlém disso, a Marca prende a presa ao limiar entre os mundos: enquanto estiver Marcada, a criatura não pode usar movimento incorpóreo, ficar **Invisível** ou entrar no Plano Etéreo; e, caso a criatura seja um Morto-Vivo, ela também não pode recuperar Pontos de Vida por meios sobrenaturais das próprias características, nem usar a ação Desengajar (Disengage).","id_classe_id":4,"id_habilidade":1092,"id_subclasse_id":156,"niveladquirido":3,"nome":"Marca Mortuária","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Antes de escolher a arma, registro quais ritos alcançam a presa. Magia bem preparada não substitui aço nem pólvora, mas abre a guarda certa e impede que um monstro transforme uma vantagem sobrenatural em sentença de morte.*\n\nVocê tem sempre preparadas as magias a seguir; elas contam como magias de Caçador para você e não contam no seu limite de magias preparadas.\n\n| Nível de Caçador | Magias |\n| --- | --- |\n| 3º | Detectar Magia [Detect Magic]\nDetectar Venenos e Doenças [Detect Poison and Disease] |\n| 5º | Ver o Invisível [See Invisibility]\nDetectar Pensamentos [Detect Thoughts] |\n| 9º | Dissipar Magia [Dispel Magic]\nProteção contra o Profano [Crooked Ward] |\n| 13º | Adivinhação [Divination]\nLocalizar Criatura [Locate Creature] |\n| 17º | Imobilizar Monstro [Hold Monster]\nSaber Lendário [Legend Lore] |\n\nAlém das magias acima, a Linha Mestra da sua Ordem é a Linha **Armadilhas e Emboscadas**: você tem sempre preparados todos os Segredos dessa Linha, adquirindo cada um assim que alcança o nível de pré-requisito do Grau correspondente, e eles não contam no seu limite de Segredos preparados.","id_classe_id":4,"id_habilidade":1093,"id_subclasse_id":157,"niveladquirido":3,"nome":"Magias e Segredos da Ordem dos Exterminadores","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Antes do primeiro golpe, observo o que a marca revela; depois dele, observo o que a dor confirma. Uma defesa catalogada deixa de ser surpresa, e uma presa ferida oferece exatamente a abertura que meu próximo ataque precisa.*\n\n- **Inquisição.** Imediatamente após aplicar sua Marca do Caçador a uma criatura, você descobre as Imunidades, Resistências e Vulnerabilidades a dano dela, além de suas imunidades a condições.\n\n- **Punição.** Uma vez por turno, quando acerta uma Presa Marcada que não esteja com todos os Pontos de Vida, você causa dano adicional igual a uma rolagem do seu Dado de Caçador.","id_classe_id":4,"id_habilidade":1094,"id_subclasse_id":157,"niveladquirido":3,"nome":"Ferramentas do Algoz","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Dez minutos num rastro dizem mais do que dez horas correndo às cegas. Sangue, testemunhas, resíduos e hábitos formam um retrato; quando a terceira peça encaixa, já não preciso enxergar a presa para marcá-la.*\n\n**Marca Antecipada.** Depois de passar 10 minutos investigando um local e reunir ao menos três pistas diferentes sobre uma criatura específica, você pode usar uma Ação Bônus para aplicar sua Marca do Caçador a ela sem precisar vê-la, desde que conheça o tipo da criatura e ela esteja no mesmo plano a até 8 quilômetros [5 milhas]. O uso da Marca é gasto normalmente. Se o alvo estiver fora do alcance ou em outro plano, a Marca falha e você percebe que o rastro esfriou.\n\n**Olhar Treinado.** Enquanto uma criatura estiver sob sua Marca, você tem Vantagem em testes de Inteligência (Arcanismo, História, Natureza ou Religião) para recordar informações sobre sua origem, seus hábitos e seus poderes. Isso não revela identidades secretas, nomes verdadeiros ou planos ocultos.","id_classe_id":4,"id_habilidade":1095,"id_subclasse_id":157,"niveladquirido":3,"nome":"Perseguidor Longínquo","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Antes de escolher a arma, registro quais ritos alcançam a presa. Magia bem preparada não substitui aço nem pólvora, mas abre a guarda certa e impede que um monstro transforme uma vantagem sobrenatural em sentença de morte.*\n\nVocê tem sempre preparadas as magias a seguir; elas contam como magias de Caçador para você e não contam no seu limite de magias preparadas.\n\n| Nível de Caçador | Magias |\n| --- | --- |\n| 3º | Salto [Jump]\nAbsorver Elementos [Absorb Elements] |\n| 5º | Alterar-se [Alter Self]\nCrescer e Encolher [Enlarge/Reduce] |\n| 9º | Pressa [Haste]\nProteção contra Energia [Protection from Energy] |\n| 13º | Polimorfia [Polymorph]\nLiberdade de Movimento [Freedom of Movement] |\n| 17º | Imobilizar Monstro [Hold Monster]\nReencarnar [Reincarnate] |\n\nAlém das magias acima, a Linha Mestra da sua Ordem é a Linha **Alquimia e Poções**: você tem sempre preparados todos os Segredos dessa Linha, adquirindo cada um assim que alcança o nível de pré-requisito do Grau correspondente, e eles não contam no seu limite de Segredos preparados.","id_classe_id":4,"id_habilidade":1096,"id_subclasse_id":158,"niveladquirido":3,"nome":"Magias e Segredos da Ordem dos Mutantes","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Meu sangue já recebeu toxinas suficientes para reconhecer veneno como matéria-prima. O corpo ficou mais pesado, resistente e difícil de matar; não foi uma bênção, apenas o resultado inevitável de sobreviver ao laboratório tantas vezes.*\n\nSeu máximo de Pontos de Vida aumenta em uma quantidade igual ao seu nível de Caçador. Sempre que você ganha outro nível nesta classe, esse máximo aumenta em 1 adicional. Além disso, você ganha Resistência a dano de veneno e imunidade à condição Envenenado.","id_classe_id":4,"id_habilidade":1097,"id_subclasse_id":158,"niveladquirido":3,"nome":"Fisiologia Mutante","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Toda fórmula tem duas colunas no meu diário: o que ela concede e o que ela cobra. Quem registra apenas a primeira termina morto, deformado ou pior; eu sobrevivi porque nunca esqueço de ler a segunda.*\n\nVocê aprende a produzir fórmulas que alteram o seu organismo. Cada fórmula apresentada a seguir possui um Efeito Benéfico e um Efeito Colateral, que são aplicados simultaneamente quando o mutagênico é consumido.\n\n- **Fórmulas Conhecidas.** Você aprende quatro Fórmulas Mutagênicas desta característica. Você aprende uma fórmula adicional ao alcançar o 7º, 11º, 15º e 18º nível de Caçador. Sempre que aprender uma nova fórmula, pode substituir uma fórmula que conhece por outra desta lista.\n\n- **Preparação.** Ao terminar um Descanso Curto ou Longo, você pode usar seus Suprimentos de Alquimista para preparar mutagênicos das fórmulas que conhece. Os frascos permanecem potentes até o início do seu próximo Descanso Curto ou Longo, quando qualquer frasco não utilizado se torna inerte.\n\n- **Limite Mutagênico.** O número máximo de frascos que você pode manter preparados e de mutagênicos que podem afetá-lo simultaneamente é determinado pelo seu nível de Caçador: um no 3º nível, dois no 7º nível e três no 15º nível.\n\n- **Consumo e Ativação.** Como uma **Ação Bônus**, você pode consumir ou injetar um mutagênico preparado, recebendo imediatamente o Efeito Benéfico e o Efeito Colateral da fórmula.\n\n- **Duração e Purgação.** Os efeitos de um mutagênico duram até você iniciar um Descanso Curto ou Longo. Você também pode usar uma **Ação** para purgar as toxinas do seu organismo, encerrando todos os Efeitos Benéficos e Colaterais dos mutagênicos ativos em você.\n\n- **Toxicidade Específica.** Seus mutagênicos são calibrados para a sua biologia. Outra criatura que consumir um deles não recebe o Efeito Benéfico e deve ser bem-sucedida em um teste de resistência de Constituição contra a CD dos seus Segredos ou fica **Envenenada** por 1 hora.\n\n#### Carapaça de Basilisco (requer 7º nível)\n\nVocê ganha Resistência a dano cortante, perfurante e concussivo. Você não pode realizar a ação Esquivar e seu deslocamento é reduzido em 3 metros [10 pés].\n\n#### Kraken Onisciente\n\nSua Inteligência e o máximo desse atributo aumentam em 3. Esse aumento passa a 4 no 11º nível e a 5 no 18º nível, até o máximo de 22. Sua Sabedoria é reduzida em 3.\n\n#### Esfinge Visionária\n\nSua Sabedoria e o máximo desse atributo aumentam em 3. Esse aumento passa a 4 no 11º nível e a 5 no 18º nível, até o máximo de 22. Sua Inteligência é reduzida em 3.\n\n#### Salamandra Ígnea\n\nVocê ganha Resistência a dano de fogo e Vulnerabilidade a dano de frio.\n\n#### Raptor Sombrio\n\nSua Destreza e o máximo desse atributo aumentam em 3. Esse aumento passa a 4 no 11º nível e a 5 no 18º nível, até o máximo de 22. Sua Força é reduzida em 3.\n\n#### Yeti Boreal\n\nVocê ganha Resistência a dano de frio e Vulnerabilidade a dano de fogo.\n\n#### Vermeluz das Cavernas\n\nVocê fica imune às condições Agarrado e Restringido. Você tem Desvantagem em testes de Força e não pode Agarrar criaturas.\n\n#### Morcego Abissal\n\nVocê ganha Visão no Escuro de 18 metros [60 pés]. Se já a possuir, o alcance aumenta em 18 metros [60 pés]. Sob luz plena, você tem Desvantagem em testes de habilidade e jogadas de ataque.\n\n#### Lobo Alfa\n\nVocê tem Vantagem em testes de Sabedoria (Percepção) baseados em audição, olfato ou visão e Desvantagem em testes de Carisma (Atuação, Enganação, Intimidação ou Persuasão).\n\n#### Górgona Prateada\n\nSua Força e o máximo desse atributo aumentam em 3. Esse aumento passa a 4 no 11º nível e a 5 no 18º nível, até o máximo de 22. Sua Destreza é reduzida em 3.\n\n#### Guepardo das Planícies\n\nSeu deslocamento aumenta em 3 metros [10 pés], ou em 4,5 metros [15 pés] a partir do 15º nível. Você tem Desvantagem em testes de Inteligência e não pode manter Concentração em magias ou rituais.\n\n#### Camaleão Espectral\n\nVocê pode usar seu modificador de Inteligência ou Sabedoria em testes de Carisma. Você tem Desvantagem em rolagens de Iniciativa.\n\n#### Lagartixa-Cicatrizante (requer 7º nível)\n\nDurante 1 hora, no início de cada um dos seus turnos, você recupera Pontos de Vida iguais ao seu Bônus de Proficiência se tiver ao menos 1 Ponto de Vida. Toda cura recebida de outra criatura tem seu valor reduzido à metade.\n\n#### Manticora Raivosa (requer 11º nível)\n\nQuando realiza a ação Atacar, você pode fazer um ataque adicional como uma Ação Bônus. Você tem Desvantagem em testes de resistência de Inteligência, Sabedoria e Carisma.\n\n#### Harpia das Montanhas (requer 11º nível)\n\nDurante 1 hora, você ganha deslocamento de voo igual ao seu deslocamento. Pela mesma duração, você tem Desvantagem em jogadas de ataque com armas.\n\n#### Quimera do Caos (requer 11º nível)\n\nSeus ataques com armas obtêm um acerto crítico com resultados 19 ou 20 no d20. Você tem Desvantagem em testes de resistência contra efeitos mentais, incluindo medo e encantamento.","id_classe_id":4,"id_habilidade":1098,"id_subclasse_id":158,"niveladquirido":3,"nome":"Fórmulas Mutagênicas","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Antes de escolher a arma, registro quais ritos alcançam a presa. Magia bem preparada não substitui aço nem pólvora, mas abre a guarda certa e impede que um monstro transforme uma vantagem sobrenatural em sentença de morte.*\n\nVocê tem sempre preparadas as magias a seguir; elas contam como magias de Caçador para você e não contam no seu limite de magias preparadas.\n\n| Nível de Caçador | Magias |\n| --- | --- |\n| 3º | Proteção contra o Mal e o Bem [Protection from Evil and Good]\nDetectar o Mal e o Bem [Detect Evil and Good] |\n| 5º | Passo Brumoso [Misty Step]\nVer Invisíveis [See Invisibility] |\n| 9º | Pressa [Haste]\nPiscar [Blink] |\n| 13º | Banimento [Banishment]\nPorta Dimensional [Dimension Door] |\n| 17º | Círculo de Teletransporte [Teleportation Circle]\nDestruição Banidora [Banishing Smite] |\n\nAlém das magias acima, a Linha Mestra da sua Ordem é a Linha **Conhecimentos Ancestrais (Sinais)**: você tem sempre preparados todos os Segredos dessa Linha, adquirindo cada um assim que alcança o nível de pré-requisito do Grau correspondente, e eles não contam no seu limite de Segredos preparados.","id_classe_id":4,"id_habilidade":1099,"id_subclasse_id":159,"niveladquirido":3,"nome":"Magias e Segredos da Ordem dos Viajantes Primordiais","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Uma boa marca não aponta apenas onde a presa está; ela transforma a própria fuga em caminho. Gravei o sinal na criatura e senti cada portal que ela tocou, como passos pesados percorrendo as raízes do Teixo.*\n\nQuando aplica a sua Marca do Caçador, a criatura se torna uma Runa de Travessia viva. Enquanto estiver no mesmo plano que você, ela pode servir como destino para Passo Rúnico e Salto Direto a qualquer distância, levando você a um espaço desocupado a até 3 metros [10 pés] dela.\n\nQuando acerta a Presa Marcada com um ataque, você pode transformar em dano de Energia tanto o dano do ataque quanto o dano adicional da Marca do Caçador. Você também conhece sempre a direção da Presa Marcada, percebe imediatamente quando ela atravessa um portal ou muda de plano e sente portais e fendas planares ativos a até 1,5 quilômetro [1 milha].","id_classe_id":4,"id_habilidade":1100,"id_subclasse_id":159,"niveladquirido":3,"nome":"Marca do Guardião","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*As fadas ensinaram que distância é apenas um acordo entre dois lugares. Minhas runas quebram esse acordo por um instante, tempo bastante para que uma lâmina, uma flecha ou o próprio caçador apareça onde a presa não esperava.*\n\nComo uma Ação Bônus, você cria uma Runa de Travessia em um espaço ou objeto que possa ver a até 9 metros [30 pés]. A runa é visível apenas para você, e você pode manter até duas runas ao mesmo tempo; ao criar uma terceira, a mais antiga desaparece.\n\n- **Passo Rúnico.** Ao realizar a ação Atacar, imediatamente antes de uma jogada de ataque, você pode se teleportar para um espaço desocupado a até 3 metros [10 pés] de uma runa que possa ver. A próxima criatura que você acertar neste turno sofre dano adicional de Energia igual a uma rolagem do seu Dado de Caçador. Uma criatura só pode sofrer esse dano uma vez por turno.\n\n- **Salto Direto.** Como uma Ação Bônus, você se teleporta para um espaço desocupado a até 3 metros [10 pés] de uma runa que possa ver.\n\n- **Arremesso Cintilante.** Depois de resolver um ataque que arremesse uma arma ou dispare uma munição, você pode se teleportar para um espaço desocupado a até 3 metros [10 pés] do ponto onde o projétil parou.\n\nNenhum desses teleportes pode atravessar mais de 9 metros [30 pés], independentemente da distância até a runa.","id_classe_id":4,"id_habilidade":1101,"id_subclasse_id":159,"niveladquirido":3,"nome":"Runas de Travessia","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Não preciso chamá-lo. Ele sente quando estou pronto para o golpe e se move antes que a palavra deixe minha boca. Há uma linha invisível entre nós, tecida de rastros, silêncios e caçadas partilhadas, que conduz cada movimento.*\n\nA sua conexão com o espírito transcende comandos verbais, concedendo os benefícios a seguir:\n\n- **Instinto Compartilhado.** Enquanto puder ver você, o espírito tem Vantagem em todos os testes de resistência.\n\n- **Ataque Coordenado.** Quando usa a ação Atacar no seu turno, você pode substituir um dos seus ataques para usar Comando, sem gastar uma Ação Bônus.","id_classe_id":4,"id_habilidade":1102,"id_subclasse_id":152,"niveladquirido":6,"nome":"Elo de Caça","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*No escuro, quem hesita morre. Aprendi a me mover antes de pensar, o corpo já sabendo onde o golpe não vai me encontrar. Passei tantas noites caçando na penumbra que o instinto tomou o lugar da razão, e hoje esquivo do perigo um instante antes de ele existir.*\n\nUma vida caçando na penumbra afiou os seus reflexos além do normal. Você ganha proficiência em testes de resistência de Destreza. Se você já tiver essa proficiência, em vez disso ganha proficiência em testes de resistência de Força ou Constituição, à sua escolha.","id_classe_id":4,"id_habilidade":1103,"id_subclasse_id":153,"niveladquirido":6,"nome":"Reflexos das Sombras","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Quanto mais sangro, mais a fera acorda, e ela cura o que o homem não aguentaria. Cada ferida só me deixa mais difícil de derrubar, porque a dor que abateria outro caçador é justamente o que desperta em mim a vitalidade monstruosa que fecha a carne no meio da luta.*\n\nA vitalidade monstruosa flui mais forte em você. O seu deslocamento aumenta em **3 metros [10 pés]** e a distância dos seus saltos aumenta em mais **3 metros [10 pés]**. Você também pode usar o seu modificador de Destreza no lugar do de Força em testes de Atletismo, e o seu modificador de Força no lugar do de Destreza em testes de Acrobacia. Além disso, uma vez por turno, ao acertar um ataque enquanto estiver transformado e **Sangrando**, você recupera **1d10** + o seu modificador de Inteligência ou Sabedoria em Pontos de Vida.","id_classe_id":4,"id_habilidade":1104,"id_subclasse_id":154,"niveladquirido":6,"nome":"Vigor da Fera","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Certa vez pensei ter sido rápido o bastante para evitar uma flecha, até perceber que eles se moveram antes de mim. Desde então, já não sei onde termina o meu reflexo e começa o instinto de milhares de criaturas empenhadas em nos manter vivos.*\n\nO enxame passa a agir por instinto para preservar você e as criaturas próximas, concedendo os benefícios a seguir:\n\n- **Barreira Viva.** Uma vez por turno, quando você sofre dano, compare o dano total com o seu nível de Caçador + seu modificador de Inteligência ou Sabedoria, à sua escolha (mínimo de +1). Se o dano for igual ou menor que esse valor, ele é reduzido a 0. Caso seja maior, você sofre todo o dano.\n\n- **Resposta Instintiva.** Quando uma criatura que você possa ver a até 9 metros [30 pés] faz uma jogada de ataque contra você ou contra um aliado a até 1,5 metro [5 pés] de você, você pode usar sua Reação para impor Desvantagem à jogada. Você também pode mover o alvo do ataque até 1,5 metro [5 pés] para um espaço desocupado. Esse movimento não provoca Ataques de Oportunidade.\n\nVocê pode usar Resposta Instintiva um número de vezes igual ao seu modificador de Inteligência ou Sabedoria (mínimo de uma vez), recuperando todos os usos gastos ao terminar um Descanso Curto ou Longo.","id_classe_id":4,"id_habilidade":1105,"id_subclasse_id":155,"niveladquirido":6,"nome":"Instinto Coletivo","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Quando me visto de fantasma, a morte não sabe mais por onde me pegar. Torno-me semi-incorpóreo, frio como a Penumbra, atravessando parede e criatura como se o peso do corpo fosse coisa opcional — e caço à vontade num estado que a própria morte hesita em tocar.*\n\nComo uma **Ação Bônus**, você adota uma forma espectral e ceifadora por 1 minuto. Enquanto durar, você tem Resistência a dano necrótico e frio, e torna-se semi-incorpóreo: pode mover-se através de criaturas e objetos (sofrendo **1d10** de dano de força se terminar o turno dentro de um objeto) e fica imune às condições **Agarrado**, **Caído** e **Restringido**.\n\nVocê adota esta forma uma vez de graça, recuperando o uso ao terminar um Descanso Longo; depois disso, pode adotá-la novamente gastando **2 Pontos de Segredo** ou um espaço de magia de **2º Círculo ou superior**.","id_classe_id":4,"id_habilidade":1106,"id_subclasse_id":156,"niveladquirido":6,"nome":"Forma do Ceifador","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Conhecer a presa serve tanto para feri-la quanto para sobreviver a ela. Depois de registrar o alcance, o veneno e o padrão de impacto, até o ataque mais brutal perde parte da surpresa que o tornava mortal.*\n\nEscolha Inteligência ou Sabedoria ao obter esta característica. Você adiciona o modificador do atributo escolhido aos testes de resistência provocados por seus Inimigos Favoritos. Além disso, sempre que sofre dano causado por um Inimigo Favorito, reduz esse dano em uma quantidade igual ao mesmo modificador (mínimo de 1).","id_classe_id":4,"id_habilidade":1107,"id_subclasse_id":157,"niveladquirido":6,"nome":"Contramedidas Protetivas","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Há um instante, depois que o mutagênico entra no sangue, em que a dor ainda pode ser separada do poder. Treinei meu corpo para encontrar esse intervalo e mantê-lo aberto enquanto a caçada exige precisão.*\n\nVocê ganha imunidade a dano de veneno. Enquanto estiver sob o efeito de ao menos um mutagênico, pode usar uma Ação Bônus para escolher um deles e suprimir seu Efeito Colateral por 1 minuto, mantendo o Efeito Benéfico. O mutagênico continua ativo para determinar o seu limite de toxicidade.\n\nDepois de usar esta característica, você não pode usá-la novamente até terminar um Descanso Longo, a menos que gaste 2 Pontos de Segredo para recuperar o uso.","id_classe_id":4,"id_habilidade":1108,"id_subclasse_id":158,"niveladquirido":6,"nome":"Supressão Alquímica","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Quando o golpe alcança meu corpo, abro uma fissura estreita no caminho dele. Parte do impacto se perde entre os mundos; se não restar nada, fecho a passagem apontada para outra presa.*\n\nQuando uma Presa Marcada ou um Inimigo Favorito acerta você com um ataque, você pode usar sua Reação para reduzir o dano em 1d10 + seu modificador de Inteligência ou Sabedoria + seu nível de Caçador.\n\n**Retaliação Planar.** Se o dano for reduzido a 0, escolha uma criatura hostil que possa ver a até 18 metros [60 pés]. Ela deve realizar um teste de resistência de Destreza contra a sua CD de Magia, sofrendo duas rolagens do seu Dado de Caçador de dano de Energia em uma falha, ou metade em um sucesso. Você pode usar esta característica um número de vezes igual ao seu modificador de Inteligência ou Sabedoria (mínimo de uma vez), recuperando todos os usos ao terminar um Descanso Longo.","id_classe_id":4,"id_habilidade":1109,"id_subclasse_id":159,"niveladquirido":6,"nome":"Ruptura do Selo","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Um só golpe já não basta. Aprendemos a atacar no mesmo instante, de modo que a presa nunca sabe de qual lado virá o próximo dente. Quando tenta responder ao primeiro bote, o segundo já encontrou a abertura deixada pela marca.*\n\nO espírito recebe os benefícios a seguir:\n\n- **Ataques Primordiais.** Quando o espírito realiza Retalhar [Rend], ele pode realizar esse ataque uma vez adicional no mesmo turno. Esse benefício permite que ele faça os dois ataques quando obedece ao seu Comando, apesar do limite normal de um ataque por Reação.\n\n- **Marca Compartilhada.** Quando Retalhar acerta uma criatura sob a sua Marca do Caçador, o ataque também causa o dano adicional da Marca.","id_classe_id":4,"id_habilidade":1110,"id_subclasse_id":152,"niveladquirido":10,"nome":"Assalto Coordenado","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A cada invocação, o espírito ocupa um pouco mais do mundo. Quando preciso de força em vez de discrição, ele cresce até as patas pesarem no chão e nenhuma criatura conseguir ignorar a massa primordial avançando contra ela.*\n\nQuando conjura Familiar de Batalha por Companheiro Primordial, você pode fazer o espírito assumir tamanho Grande. Enquanto estiver Grande, ele tem Vantagem em testes de Força realizados para Agarrar ou Empurrar uma criatura, ou para evitar ou escapar de um Agarrão.","id_classe_id":4,"id_habilidade":1111,"id_subclasse_id":152,"niveladquirido":10,"nome":"Forma Aumentada","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A penumbra ensina duas lições: um golpe errado ainda pode encontrar o caminho, e uma posição ruim só existe enquanto eu permaneço nela. Ajusto a lâmina no último instante e desapareço antes que a presa consiga responder.*\n\nSeu domínio sobre as sombras aprimora a sua precisão e permite que você atravesse o campo sem ser alcançado, concedendo os benefícios a seguir:\n\n- **Precisão Tenebrosa.** Uma vez por turno, quando você erra uma jogada de ataque com arma, pode rolar o seu Dado de Caçador e adicionar o resultado à jogada de ataque original, potencialmente transformando o erro em acerto.\n\n- **Movimento das Sombras.** Como uma **Ação Bônus**, você se teletransporta para um espaço desocupado que possa ver a até **9 metros [30 pés]** e que esteja em Penumbra ou Escuridão.","id_classe_id":4,"id_habilidade":1112,"id_subclasse_id":153,"niveladquirido":10,"nome":"Executor Umbral","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A jaula ficou maior, a coleira mais comprida. A fera fecha minhas feridas sozinha agora, e quem sente o uivo dela não se levanta mais tão rápido. Sangro no início de um turno e, no seguinte, a marca já sumiu — o monstro não conhece cansaço, e emprestou-me esse dom cru.*\n\nA sua carne regenera por conta própria enquanto a fera estiver desperta. No início de cada um dos seus turnos em que estiver **Sangrando** com ao menos 1 Ponto de Vida, você recupera **1 + o seu modificador de Constituição** em Pontos de Vida, com um mínimo de 1.\n\nAlém disso, o seu uivo deixa marcas que não cicatrizam: uma criatura que falhe no teste de resistência do seu **Uivo do Despertar** não pode recuperar Pontos de Vida até o início do seu próximo turno.","id_classe_id":4,"id_habilidade":1113,"id_subclasse_id":154,"niveladquirido":10,"nome":"Regeneração Bestial","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Começaram como um zumbido no ombro; agora avançam comigo como uma maré. Cada comando ganhou peso, cada defesa ganhou asas e até a presa mais resistente sente o campo inteiro mudar quando a colônia decide ocupar o espaço ao meu redor.*\n\nA colônia cresce e aprimora as capacidades do seu Enxame Simbiótico, concedendo os benefícios a seguir:\n\n- **Voo Simbiótico.** Você ganha deslocamento de voo igual ao seu deslocamento de escalada e pode pairar.\n\n- **Força Multiplicada.** Quando realiza um teste de Força (Atletismo) para Agarrar ou Empurrar uma criatura, ou para evitar ou escapar de um Agarrão, você adiciona uma rolagem do seu Dado de Caçador ao resultado.\n\n- **Marca da Colônia.** Quando usa o seu Enxame Simbiótico contra uma criatura sob a sua Marca do Caçador, você escolhe duas opções diferentes para afetá-la, em vez de uma.","id_classe_id":4,"id_habilidade":1114,"id_subclasse_id":155,"niveladquirido":10,"nome":"Enxame Evoluído","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Primeiro o rito. Depois, se ele não quiser sair por bem, a força. Conheço as cerimônias que arrancam o espírito da carne alheia e destilo a água benta que cura os meus e queima os mortos — o ofício inteiro, do incenso à lâmina, aprendido para não recuar diante de nada.*\n\nVocê aprofunda os ritos da Ordem e pode conjurar *Cerimônia [Ceremony]*; para você, essa magia não exige componentes materiais nem qualquer custo. Sempre que conclui a cerimônia, você pode, como parte dela, realizar um exorcismo: uma criatura possuída ou um espírito possessor a até **9 metros [30 pés]** faz um teste de resistência de Carisma contra a sua CD de Magia e, em uma falha, o espírito é expelido do hospedeiro e a possessão termina.\n\nA cerimônia também destila a água benta da Ordem, guardada em um **Frasco Consagrado**: um pequeno vidro grosso, lacrado com cera e marcado com o selo de Cessira, contendo uma água límpida, fria e levemente luminosa que recusa qualquer mão que não seja a de um exorcista. Você mantém um número de Frascos Consagrados igual ao seu **Bônus de Proficiência**; eles servem apenas às suas habilidades de classe e perdem a potência se entregues a estranhos ou comercializados. Como uma **Ação Bônus**, você usa um Frasco Consagrado de uma destas formas: bebendo-o, ou ungindo com ele um aliado a até **1,5 metro [5 pés]**, para recuperar **duas rolagens do seu Dado de Caçador mais o seu nível de Caçador** em Pontos de Vida e remover um nível de **Exaustão** que a criatura esteja sofrendo; ou arremessando-o numa criatura a até **9 metros [30 pés]**, que sofre **uma rolagem do seu Dado de Caçador** de dano radiante — mortos-vivos e criaturas possessoras sofrem o dobro e não podem recuperar Pontos de Vida até o fim do próximo turno deles.","id_classe_id":4,"id_habilidade":1115,"id_subclasse_id":156,"niveladquirido":10,"nome":"Rito de Exorcismo","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Há uma luz que os mortos não suportam encarar, e eu carrego uma comigo. Ergo a lanterna, digo a palavra, e o que deveria estar descansando recua diante do brilho, amedrontado e trôpego, lembrado à força de que o seu lugar não é mais entre os que ainda respiram.*\n\nComo uma **Ação Mágica**, você ergue a sua Lanterna do Véu e censura os mortos-vivos. Cada morto-vivo à sua escolha a até **9 metros [30 pés]** faz um teste de resistência de Sabedoria contra a sua CD de Magia. Em uma falha, a criatura sofre dano radiante igual a **um número de d8 igual ao seu modificador de Inteligência ou Sabedoria** e fica **Amedrontada** e **Incapacitada** por 1 minuto, tentando se afastar de você nos turnos dela. O efeito termina mais cedo se a criatura sofrer dano, se você ficar Incapacitado ou se você morrer. Em um sucesso, a criatura sofre apenas metade do dano.\n\nDepois de usar esta característica, você não pode usá-la novamente até terminar um Descanso Curto ou Longo, a menos que gaste **3 Pontos de Segredo** para recuperar o uso.","id_classe_id":4,"id_habilidade":1116,"id_subclasse_id":156,"niveladquirido":10,"nome":"Afastar Mortos-Vivos","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Depois de estudar uma espécie por tempo suficiente, basta marcar um exemplar para que todos os seus semelhantes se tornem legíveis. Um golpe bem colocado atravessa o alvo e ensina aos monstros próximos que o método serve para cada um deles.*\n\nUma criatura sob a sua Marca do Caçador também conta como um Inimigo Favorito para você.\n\nAlém disso, uma vez em cada um dos seus turnos, quando acerta uma Presa Marcada, cada criatura hostil do mesmo tipo a até 3 metros [10 pés] dela sofre dano igual a uma rolagem do seu Dado de Caçador, do mesmo tipo do ataque. Se uma dessas criaturas também for um Inimigo Favorito, ela sofre ainda o dano adicional concedido por essa característica.","id_classe_id":4,"id_habilidade":1117,"id_subclasse_id":157,"niveladquirido":10,"nome":"Marca do Carrasco","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Uma presa marcada não esconde a carne de mim. Quando encontro a fissura certa, empurro para dentro dela aquilo que meu próprio corpo aprendeu a suportar e deixo que o monstro pague o preço da minha fórmula.*\n\nEnquanto uma criatura estiver sob a sua Marca do Caçador, ela não pode mudar de forma por magia ou outro efeito, a menos que seja bem-sucedida em um teste de resistência de Sabedoria contra a sua CD de Magia.\n\nAlém disso, quando obtém um acerto crítico com um ataque com arma ou Golpe Desarmado contra uma Presa Marcada ou um Inimigo Favorito, escolha um mutagênico ativo em você. Até o final do seu próximo turno, o alvo sofre o Efeito Colateral desse mutagênico e você o ignora. Você não pode transferir o mesmo Efeito Colateral mais de uma vez com esta característica.","id_classe_id":4,"id_habilidade":1118,"id_subclasse_id":158,"niveladquirido":10,"nome":"Estigma Hermético","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Depois de tantas travessias, já não penso em passos. Cada golpe escolhe um novo ponto do campo, e cada ponto abre outra linha de ataque; para a presa, parece que a perseguição vem de todos os lados.*\n\n- **Salto em Travessia.** Imediatamente depois de resolver uma jogada de ataque com arma no seu turno, acertando ou errando, você pode se teleportar para um espaço desocupado que possa ver a até 3 metros [10 pés].\n\n- **Golpe em Cadeia.** Uma vez por turno, imediatamente após esse teleporte, você pode fazer um ataque adicional contra uma criatura diferente que esteja ao alcance da sua arma. Esse ataque pode receber o dano adicional de Passo Rúnico se o alvo ainda não tiver sofrido esse dano neste turno.","id_classe_id":4,"id_habilidade":1119,"id_subclasse_id":159,"niveladquirido":10,"nome":"Andarilho do Horizonte","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*O que corre nas minhas veias corre nas dele. Não existe bênção que eu aceite sozinho, porque um caçador e seu espírito são partes do mesmo pacto; quando a magia fortalece um de nós, o vínculo conduz o restante até o outro.*\n\nQuando conjura uma magia que tenha apenas você como alvo e não afete uma área, você também pode afetar o seu Companheiro Primordial com a mesma magia, desde que ele esteja a até 9 metros [30 pés] de você.","id_classe_id":4,"id_habilidade":1120,"id_subclasse_id":152,"niveladquirido":14,"nome":"Comunhão Primordial","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Na hora incerta, cada respiro meu é um golpe, e a presa nunca conta os certos. Enquanto houver penumbra à minha volta, a lentidão do primeiro instante vira o ritmo de todos os outros, e o inimigo se vê aparando dois botes onde esperava aparar um só.*\n\nEnquanto você se mantiver em Penumbra ou Escuridão, você pode fazer o ataque adicional do Caçador das Sombras em todos os seus turnos de combate, e não apenas no primeiro. Nos turnos após o primeiro, porém, o dano extra desse ataque é igual à metade do seu nível de Caçador, arredondada para baixo (em vez do seu nível completo).","id_classe_id":4,"id_habilidade":1121,"id_subclasse_id":153,"niveladquirido":14,"nome":"Ataques Velozes","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Já não sei onde termina o caçador e começa a coisa antiga que mora em mim. Só sei que, quando deveria cair, eu me levanto, e o medo nos olhos da presa vira a minha arma.*\n\nA fúria do seu uivo derruba os que vacilam. Quando uma criatura falha no teste de resistência do seu **Uivo do Despertar**, ela também fica **Caída** ou é empurrada **3 metros [10 pés]** para longe de você (à sua escolha).\n\nAlém disso, a sua vitalidade monstruosa o arranca da beira da morte. Se você cair a 0 Pontos de Vida sem morrer de imediato enquanto estiver transformado, os seus Pontos de Vida passam a ser iguais a **duas vezes o seu nível de Caçador**. Você pode fazer isso uma vez por Descanso Longo.","id_classe_id":4,"id_habilidade":1122,"id_subclasse_id":154,"niveladquirido":14,"nome":"Ímpeto Ancião","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Eles já não esperam por comando; sentem comigo quem precisa continuar de pé. Quando o perigo alcança um aliado, a colônia atravessa o campo como uma muralha viva, desvia o golpe e carrega a vítima para fora antes que o inimigo possa reagir.*\n\nSua Resposta Instintiva pode ser usada quando qualquer criatura a até 9 metros [30 pés] de você for alvo de uma jogada de ataque ou sofrer dano causado por um efeito que exija um teste de resistência. Quando a utiliza, aplique o benefício correspondente:\n\n- **Defesa contra Ataques.** Você impõe Desvantagem à jogada de ataque. Se o ataque ainda acertar, o alvo recebe Resistência contra o dano desse ataque.\n\n- **Defesa contra Efeitos.** O alvo realiza o teste de resistência normalmente e recebe Resistência contra o dano causado pelo efeito.\n\n- **Resgate Tático.** Depois de resolver o ataque ou efeito, você pode mover a criatura protegida até 9 metros [30 pés] para um espaço desocupado. Esse movimento não provoca Ataques de Oportunidade.","id_classe_id":4,"id_habilidade":1123,"id_subclasse_id":155,"niveladquirido":14,"nome":"Colmeia Instintiva","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Já cruzei o Véu e voltei; a morte e eu somos velhos conhecidos, e ela não me assusta mais. Aprendi a andar do outro lado e a trazer os pés de volta, de modo que cair não é mais o fim da caçada — é só mais um limiar que eu atravesso.*\n\nO seu domínio sobre a morte se torna quase absoluto. Enquanto estiver na sua Forma do Ceifador, você tem Resistência a dano concussivo, perfurante e cortante; os seus Pontos de Vida não podem ser reduzidos por efeitos de mortos-vivos; e a sua Força não pode ser drenada.","id_classe_id":4,"id_habilidade":1124,"id_subclasse_id":156,"niveladquirido":14,"nome":"Ceifador Imortal","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Na minha luz, ninguém é invisível, e ninguém atravessa a parede pra fugir. A lanterna arranca segredos até dos mortos e prende na claridade tudo o que tentaria escapar incorpóreo — sob o seu brilho, o intruso descobre que a única saída é aquela que eu decidir permitir.*\n\nA sua lanterna aprende a arrancar segredos dos mortos. Você conhece a magia *Falar com Mortos [Speak with Dead]* e pode conjurá-la por meio da sua Lanterna do Véu, sem gastar espaços de magia, um número de vezes igual ao seu modificador de **Inteligência ou Sabedoria**, à sua escolha (mínimo de uma vez). Você recupera todos os usos gastos ao terminar um Descanso Longo. Além disso, enquanto estiver segurando a lanterna, criaturas dentro da luz dela não podem usar movimento incorpóreo nem se beneficiar de estar **Invisíveis**.","id_classe_id":4,"id_habilidade":1125,"id_subclasse_id":156,"niveladquirido":14,"nome":"Luz Reveladora","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*O primeiro golpe mostra o ombro, o quadril e a intenção da criatura. Se ela tentar repetir o movimento, encontra minha guarda esperando no lugar certo; depois de uma abertura, o resto do padrão fica simples.*\n\nQuando uma criatura acerta você com um ataque, você recebe +4 na Classe de Armadura contra todos os ataques subsequentes realizados por ela até o final do turno atual.","id_classe_id":4,"id_habilidade":1126,"id_subclasse_id":157,"niveladquirido":14,"nome":"Guarda do Executor","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Trocar uma fórmula durante a luta parece loucura até a presa mudar de tática. Então um frasco errado vira sentença, e a mão treinada que purga um sangue e injeta outro vale mais do que qualquer armadura.*\n\nComo uma Ação Bônus, você pode encerrar um mutagênico ativo em si e consumir um novo mutagênico preparado como parte da mesma ação. O novo mutagênico aplica normalmente seus Efeitos Benéfico e Colateral. Você pode usar esta característica um número de vezes igual ao seu modificador de Inteligência ou Sabedoria (mínimo de uma vez) e recupera todos os usos ao terminar um Descanso Longo.\n\nAlém disso, uma vez por turno, quando acerta uma Presa Marcada, causa 1d4 de dano adicional para cada mutagênico ativo em você, até 3d4. Escolha o tipo desse dano entre concussivo, cortante, perfurante, necrótico ou veneno.","id_classe_id":4,"id_habilidade":1127,"id_subclasse_id":158,"niveladquirido":14,"nome":"Transfusão Mutagênica","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Os caminhos do Teixo já não se fecham quando passo. Posso alargá-los o bastante para levar outra pessoa comigo, desde que ela confie no instante em que o chão desaparece e outro mundo toma o lugar.*\n\nA distância máxima que você pode se teleportar em direção a uma Runa de Travessia aumenta para 18 metros [60 pés]. Quando usa Salto Direto, você também pode teleportar uma criatura voluntária que possa ver a até 1,5 metro [5 pés] de você para um espaço desocupado a até 1,5 metro [5 pés] do seu destino.\n\nVocê pode levar uma criatura dessa forma um número de vezes igual ao seu modificador de Inteligência ou Sabedoria (mínimo de uma vez), recuperando todos os usos ao terminar um Descanso Longo.","id_classe_id":4,"id_habilidade":1128,"id_subclasse_id":159,"niveladquirido":14,"nome":"Véu Desfeito","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Conheci apenas uma vez a forma completa do espírito, e desde então reconheço o peso daquela presença em cada pegada. Quando libero todo o pacto, a criatura que caminhava ao meu lado se ergue como a própria natureza decidida a caçar.*\n\nVocê adquire o Segredo do Caçador exclusivo desta Ordem, chamado Forma Primordial Suprema.\n\n**Custo: 4 Pontos de Segredo.** Como uma **Ação Bônus**, você faz o seu Companheiro Primordial alcançar a forma completa por 1 hora. Pela duração, Familiar de Batalha é tratada como conjurada com um espaço de magia de **9º Círculo** para determinar todas as estatísticas e características que dependam do Círculo da magia.\n\nO máximo de Pontos de Vida do espírito é recalculado conforme o novo Círculo, e ele recupera Pontos de Vida até atingir esse máximo. Além disso, o espírito se torna Enorme pela duração.","id_classe_id":4,"id_habilidade":1129,"id_subclasse_id":152,"niveladquirido":18,"nome":"Forma Primordial Suprema","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Quando espalho meus aparatos sob a noite que carrego, o campo inteiro se transforma numa emboscada. Meus aliados enxergam apenas sombras comuns; para a presa, porém, cada passo atravessa um breu impossível e termina sob a mira de outra armadilha.*\n\nVocê adquire o Segredo do Caçador exclusivo desta Ordem, chamado Campo de Caça Noturno.\n\n**Custo: 4 Pontos de Segredo.** Como uma **Ação**, você ativa o Segredo Armadilha Final sem gastar Pontos de Segredo adicionais, aplicando as seguintes alterações:\n\n- A área da Armadilha Final passa a ter **18 metros [60 pés]** de raio.\n\n- Para seus inimigos, a área é Escuridão mágica, considerada um efeito de **6º Círculo** para determinar se suprime uma luz mágica. Para você e seus aliados, ela é Escuridão não mágica.\n\n- O dano causado pelas armadilhas é psíquico, independentemente do tipo escolhido ao preparar Armadilha Final.\n\n- Quando usa sua Reação para ativar uma armadilha contra uma criatura, você pode fazer um ataque contra ela como parte da mesma Reação. Você escolhe realizar esse ataque imediatamente antes ou depois de resolver o efeito da armadilha.\n\nO Campo de Caça Noturno segue todas as demais regras de Armadilha Final, incluindo sua duração, o gatilho das armadilhas e o teste de resistência.","id_classe_id":4,"id_habilidade":1130,"id_subclasse_id":153,"niveladquirido":18,"nome":"Campo de Caça Noturno","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A fera e eu já não brigamos. Somos a mesma coisa agora, e ela vem quando chamo, cresce quando uivo, e o mundo inteiro treme. Não há mais coleira, nem jaula, nem homem e monstro separados — só um caçador que aprendeu a ser, quando precisa, a própria caçada.*\n\nVocê adquire o Segredo do Caçador exclusivo desta Ordem, chamado Despertar Final.\n\n**Custo: 4 Pontos de Segredo.** Como uma **Ação Bônus**, você solta a fera por completo por 1 minuto. Enquanto durar, a sua Forma Desperta torna-se Grande (se ainda não for) e você ganha Pontos de Vida Temporários iguais a **duas vezes o seu nível de Caçador**. Os seus Golpes Predatórios passam a fazer um Golpe Desarmado adicional quando usados como **Ação Bônus**. Você conta como **Sangrando** para os efeitos de cura da sua Forma Desperta — o Vigor da Fera e a Regeneração Bestial passam a funcionar mesmo que você esteja com os Pontos de Vida cheios — e a sua carne se refaz como a magia *Regenerar [Regenerate]*: se você tiver perdido qualquer parte do corpo que não seja a cabeça, ela volta a crescer ao longo da duração. Por fim, você fica imune às condições **Amedrontado** e **Enfeitiçado**.","id_classe_id":4,"id_habilidade":1131,"id_subclasse_id":154,"niveladquirido":18,"nome":"Despertar Final","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A mão que antes carregava uma chave agora carrega uma criatura inteira. Quando libero toda a força da colônia, milhares de corpos se comprimem numa única forma colossal, capaz de agarrar, esmagar e proteger como se o próprio enxame tivesse fechado o punho.*\n\nVocê adquire o Segredo do Caçador exclusivo desta Ordem, chamado Mão da Colônia.\n\n**Custo: 4 Pontos de Segredo.** Como uma **Ação**, você faz a magia Mãos Mágicas criada pela sua Simbiose do Enxame se transformar numa Mão de Bigby [Bigby''s Hand]. Se a magia Mãos Mágicas não estiver conjurada, você a conjura como parte da mesma ação antes de transformá-la.\n\nA Mão de Bigby é conjurada como uma magia de **6º Círculo**, dura **1 minuto** e não exige Concentração. Ela assume a aparência do seu enxame e segue todas as demais regras da magia, usando a sua CD de Magia e o seu modificador de ataque de magia.","id_classe_id":4,"id_habilidade":1132,"id_subclasse_id":155,"niveladquirido":18,"nome":"Mão da Colônia","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Onde eu finco a minha lanterna, o Véu se fecha, e nada que não devia passar, passa. Consagro o solo com água benta e palavra antiga, transformando um lugar qualquer em fronteira selada — um posto avançado meu, do qual a morte fica do lado de fora, batendo em vão.*\n\nVocê adquire o Segredo do Caçador exclusivo desta Ordem, chamado Santuário do Véu.\n\n**Custo: 4 Pontos de Segredo.** Em um ritual, você conjura *Consagração [Hallow]* ou *Interdição [Forbiddance]*, usando um Frasco Consagrado no lugar do componente material e de qualquer custo em ouro.\n\nVocê também pode vincular a sua Lanterna do Véu a um local que tenha consagrado dessa forma: enquanto o vínculo durar, o local permanece permanentemente sob o efeito da magia escolhida, sem que você precise mantê-lo. Gastando **4 Pontos de Segredo**, você pode conjurar *Palavra de Retorno [Word of Recall]* para esse local consagrado. Ao vincular um novo local, o vínculo com o anterior se desfaz.","id_classe_id":4,"id_habilidade":1133,"id_subclasse_id":156,"niveladquirido":18,"nome":"Santuário do Véu","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Há presas para as quais não preparo retorno, contenção ou segundo plano. Quando faço o sinal final, toda anotação converge numa única sentença: nenhuma resistência importa, nenhuma cura chega e cada golpe aproxima a execução.*\n\nVocê adquire o Segredo do Caçador exclusivo desta Ordem, chamado Caçada Final.\n\n**Custo: 4 Pontos de Segredo.** Quando aplica sua Marca do Caçador a uma criatura, pode declará-la alvo da Caçada Final. Durante 1 minuto ou até o alvo morrer, o efeito não pode ser transferido e concede os seguintes benefícios:\n\n- O alvo não pode se beneficiar de Resistência contra dano causado por seus ataques, suas magias ou suas características.\n\n- O alvo não pode recuperar Pontos de Vida.\n\n- Quando você o acerta com um ataque com arma, ele sofre dano adicional igual a duas rolagens do seu Dado de Caçador, em vez do dano adicional normal da Marca do Caçador.","id_classe_id":4,"id_habilidade":1134,"id_subclasse_id":157,"niveladquirido":18,"nome":"Caçada Final","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Passei anos mantendo cada essência em seu frasco, com medo de que juntas me consumissem. Agora conheço cada reação pelo nome; quando abro todas de uma vez, o monstro resultante ainda responde à minha vontade.*\n\nVocê adquire o Segredo do Caçador exclusivo desta Ordem, chamado Forma Quimérica.\n\n**Custo: 4 Pontos de Segredo.** Como uma Ação Bônus, você ativa por 1 minuto todos os mutagênicos que tem preparados. Pela duração, recebe apenas os Efeitos Benéficos deles. Você também ganha um deslocamento de escalada, natação ou voo igual ao seu deslocamento, à sua escolha, e Resistência a dois tipos de dano à sua escolha.\n\nQuando a forma termina, todos os seus mutagênicos ficam inativos por 1 hora. Você só pode usar este Segredo novamente depois que eles voltarem a ficar ativos.","id_classe_id":4,"id_habilidade":1135,"id_subclasse_id":158,"niveladquirido":18,"nome":"Forma Quimérica","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*No alto do Teixo, cada plano parece uma folha ao alcance da mão. Escolho a rota antes de descansar e, quando a caçada chama, abro o caminho sem chave, círculo ou oferenda.*\n\nVocê adquire o Segredo do Caçador exclusivo desta Ordem, chamado Caminho Final. Você aprende Portal Arcano [Arcane Gate], Palavra de Retorno [Word of Recall], Etereidade [Etherealness], Mansão Magnífica de Mordenkainen [Mordenkainen''s Magnificent Mansion], Teletransporte [Teleport] e Viagem Planar [Plane Shift].\n\n**Custo: 4 Pontos de Segredo.** Ao terminar um Descanso Longo, escolha duas dessas magias. Elas ficam preparadas e não contam no seu limite de magias preparadas. Você pode conjurar cada magia escolhida uma vez gastando 4 Pontos de Segredo, sem gastar espaço de magia nem fornecer componentes materiais. Depois disso, não pode conjurá-la novamente por este Segredo até escolhê-la após outro Descanso Longo.","id_classe_id":4,"id_habilidade":1136,"id_subclasse_id":159,"niveladquirido":18,"nome":"Caminho Final","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A primeira coisa que aprendi na Ordem foi a calar a boca; a segunda, a escutar. Só depois de provar as duas me deixaram escolher o caminho que faria da minha caçada algo maior do que sobreviver: um propósito com nome próprio, com mestres e com uma trilha só minha.*\n\nVocê se filia a uma Ordem do Caçador, uma tradição que define o foco e o estilo da sua caça, como a Aliança Selvagem, os Exterminadores ou o Crepúsculo. Você recebe as características de 3º nível da Ordem escolhida imediatamente e ganha características adicionais nos níveis 6º, 10º, 14º e 18º.\n\nA sua Ordem também define a sua Linha Mestra entre as três Linhas de Segredos: Aliança Selvagem, Exterminadores e Crepúsculo têm **Armadilhas e Emboscadas**; Viajantes Primordiais e Exorcistas têm **Conhecimentos Ancestrais (Sinais)**; e Enxame, Mutantes e Despertar têm **Alquimia e Poções**.\n\n- [Ordem da Aliança Selvagem](?subclasse=ordem-da-alianca-selvagem-rework)\n- [Ordem do Crepúsculo](?subclasse=ordem-do-crepusculo-rework)\n- [Ordem do Despertar](?subclasse=ordem-do-despertar-rework)\n- [Ordem do Enxame](?subclasse=ordem-do-enxame-rework)\n- [Ordem dos Exorcistas](?subclasse=ordem-dos-exorcistas-rework)\n- [Ordem dos Exterminadores](?subclasse=ordem-dos-exterminadores-rework)\n- [Ordem dos Mutantes](?subclasse=ordem-dos-mutantes-rework)\n- [Ordem dos Viajantes Primordiais](?subclasse=ordem-dos-viajantes-primordiais-rework)","id_classe_id":4,"id_habilidade":2100000000,"id_subclasse_id":null,"niveladquirido":3,"nome":"Ordem do Caçador","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Com o tempo, o rito aprofunda e a marca cresce junto comigo; o que antes era um sussurro vira costume, e o costume vira instinto. Anoto cada camada nova como quem conta um anel no tronco: prova silenciosa de que a Ordem já não é uma escolha, e sim parte de mim.*\n\nVocê ganha a característica de 6º nível concedida pela sua Ordem do Caçador, a tradição que você escolheu no 3º nível. As opções estão descritas a seguir, em spoilers.\n\n- [Ordem da Aliança Selvagem](?subclasse=ordem-da-alianca-selvagem-rework)\n- [Ordem do Crepúsculo](?subclasse=ordem-do-crepusculo-rework)\n- [Ordem do Despertar](?subclasse=ordem-do-despertar-rework)\n- [Ordem do Enxame](?subclasse=ordem-do-enxame-rework)\n- [Ordem dos Exorcistas](?subclasse=ordem-dos-exorcistas-rework)\n- [Ordem dos Exterminadores](?subclasse=ordem-dos-exterminadores-rework)\n- [Ordem dos Mutantes](?subclasse=ordem-dos-mutantes-rework)\n- [Ordem dos Viajantes Primordiais](?subclasse=ordem-dos-viajantes-primordiais-rework)","id_classe_id":4,"id_habilidade":2100000001,"id_subclasse_id":null,"niveladquirido":6,"nome":"Habilidade da Ordem","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Fio a corda, ajusto a mira, fortaleço o braço; cada ajuste pavimenta outro centímetro de poder. Anoto no diário que não busco atalhos nem prodígios, mas o hábito teimoso de melhorar um dedo por vez, até a estrada adiante ficar larga o bastante para eu correr sem tropeçar.*\n\nVocê ganha a característica **Aprimoramento de Atributo ou Talento**, conforme descrito no 4º nível.","id_classe_id":4,"id_habilidade":2100000002,"id_subclasse_id":null,"niveladquirido":8,"nome":"Aprimoramento de Atributo ou Talento","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*O rito afunda até o osso: aquilo que eu antes chamava em grito agora atende até no silêncio. Anoto que a minha trilha deixou de ser decisão do momento e virou marca de nascença — carrego o caminho por dentro, aonde quer que a caçada resolva me levar dessa vez.*\n\nVocê ganha a característica de 10º nível concedida pela sua Ordem do Caçador, a tradição que você escolheu no 3º nível. As opções estão descritas a seguir, em spoilers.\n\n- [Ordem da Aliança Selvagem](?subclasse=ordem-da-alianca-selvagem-rework)\n- [Ordem do Crepúsculo](?subclasse=ordem-do-crepusculo-rework)\n- [Ordem do Despertar](?subclasse=ordem-do-despertar-rework)\n- [Ordem do Enxame](?subclasse=ordem-do-enxame-rework)\n- [Ordem dos Exorcistas](?subclasse=ordem-dos-exorcistas-rework)\n- [Ordem dos Exterminadores](?subclasse=ordem-dos-exterminadores-rework)\n- [Ordem dos Mutantes](?subclasse=ordem-dos-mutantes-rework)\n- [Ordem dos Viajantes Primordiais](?subclasse=ordem-dos-viajantes-primordiais-rework)","id_classe_id":4,"id_habilidade":2100000003,"id_subclasse_id":null,"niveladquirido":10,"nome":"Habilidade da Ordem","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A chama não cresce por capricho; cresce por hábito. Corrijo o passo, alongo o fôlego e ensino a mão a não tremer, anotando cada correção com a certeza de que é a soma dessas teimosias miúdas, e não um dom repentino, que pavimenta o poder que ainda vou precisar.*\n\nVocê ganha a característica **Aprimoramento de Atributo ou Talento**, conforme descrito no 4º nível.","id_classe_id":4,"id_habilidade":2100000004,"id_subclasse_id":null,"niveladquirido":12,"nome":"Aprimoramento de Atributo ou Talento","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Minha presença carimba o espaço; a linhagem não é lembrança, é farol aceso. Anoto que o rito, já velho dentro de mim, agora projeta um feixe que só quem carrega o mesmo sinal enxerga — e por ele mapeio rotas onde todos os outros só conseguem ver escuridão fechada.*\n\nVocê ganha a característica de 14º nível concedida pela sua Ordem do Caçador, a tradição que você escolheu no 3º nível. As opções estão descritas a seguir, em spoilers.\n\n- [Ordem da Aliança Selvagem](?subclasse=ordem-da-alianca-selvagem-rework)\n- [Ordem do Crepúsculo](?subclasse=ordem-do-crepusculo-rework)\n- [Ordem do Despertar](?subclasse=ordem-do-despertar-rework)\n- [Ordem do Enxame](?subclasse=ordem-do-enxame-rework)\n- [Ordem dos Exorcistas](?subclasse=ordem-dos-exorcistas-rework)\n- [Ordem dos Exterminadores](?subclasse=ordem-dos-exterminadores-rework)\n- [Ordem dos Mutantes](?subclasse=ordem-dos-mutantes-rework)\n- [Ordem dos Viajantes Primordiais](?subclasse=ordem-dos-viajantes-primordiais-rework)","id_classe_id":4,"id_habilidade":2100000005,"id_subclasse_id":null,"niveladquirido":14,"nome":"Habilidade da Ordem","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Se não moldo o poder, ele me molda. Então lapido os ossos por dentro e afio a disciplina até ela brilhar, anotando cada ganho como quem registra uma alavanca nova — não procuro atalhos, procuro pontos de apoio para erguer aquilo que antes eu não conseguia sequer mover do lugar.*\n\nVocê ganha a característica **Aprimoramento de Atributo ou Talento**, conforme descrito no 4º nível.","id_classe_id":4,"id_habilidade":2100000006,"id_subclasse_id":null,"niveladquirido":16,"nome":"Aprimoramento de Atributo ou Talento","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*A linhagem abre as asas dentro de mim, e o mundo acusa o golpe. Anoto que há um contorno novo nos meus passos, uma assinatura que dobra o horizonte — o rito chegou ao ponto em que já não sou eu quem o carrega, e sim ele quem me carrega adiante.*\n\nVocê ganha a característica de 18º nível concedida pela sua Ordem do Caçador, a tradição que você escolheu no 3º nível. As opções estão descritas a seguir, em spoilers.\n\n- [Ordem da Aliança Selvagem](?subclasse=ordem-da-alianca-selvagem-rework)\n- [Ordem do Crepúsculo](?subclasse=ordem-do-crepusculo-rework)\n- [Ordem do Despertar](?subclasse=ordem-do-despertar-rework)\n- [Ordem do Enxame](?subclasse=ordem-do-enxame-rework)\n- [Ordem dos Exorcistas](?subclasse=ordem-dos-exorcistas-rework)\n- [Ordem dos Exterminadores](?subclasse=ordem-dos-exterminadores-rework)\n- [Ordem dos Mutantes](?subclasse=ordem-dos-mutantes-rework)\n- [Ordem dos Viajantes Primordiais](?subclasse=ordem-dos-viajantes-primordiais-rework)","id_classe_id":4,"id_habilidade":2100000007,"id_subclasse_id":null,"niveladquirido":18,"nome":"Habilidade da Ordem","nome_ingles":null,"table_only":false,"tags_json":[]},{"descricao":"*Cheguei às portas maiores pela soma de portas pequenas. Agora cada respiração pesa como promessa cumprida, e anoto no diário, com a mão enfim firme, que o caminho inteiro coube nesses ajustes miúdos que ninguém viu — o último parafuso apertado no motor do peito, que agora ronca puro.*\n\nVocê ganha a característica **Aprimoramento de Atributo ou Talento**, conforme descrito no 4º nível.","id_classe_id":4,"id_habilidade":2100000008,"id_subclasse_id":null,"niveladquirido":19,"nome":"Aprimoramento de Atributo ou Talento","nome_ingles":null,"table_only":false,"tags_json":[]}],"home.tbrecursoclasse":[{"id_classe_id":4,"id_recurso":2731,"id_subclasse_id":null,"nivel":null,"nome":"Proficiência","reset":null,"slug":"proficiencia","tipo":"table-only","valor":null,"valores_json":{"1":"+2","13":"+5","17":"+6","5":"+3","9":"+4"}},{"id_classe_id":4,"id_recurso":2732,"id_subclasse_id":null,"nivel":null,"nome":"Dado de Caçador","reset":null,"slug":"dado-de-cacador","tipo":"table-only","valor":null,"valores_json":{"1":"d4","11":"d10","15":"d12","3":"d6","7":"d8"}},{"id_classe_id":4,"id_recurso":2733,"id_subclasse_id":null,"nivel":null,"nome":"1º","reset":null,"slug":"1o","tipo":"table-only","valor":null,"valores_json":{"1":"2","10":"4","11":"4","12":"4","13":"4","14":"4","15":"4","16":"4","17":"4","18":"4","19":"4","2":"2","20":"4","3":"3","4":"3","5":"4","6":"4","7":"4","8":"4","9":"4"}},{"id_classe_id":4,"id_recurso":2737,"id_subclasse_id":null,"nivel":null,"nome":"Inimigo Favorito","reset":null,"slug":"inimigo-favorito","tipo":"choice","valor":null,"valores_json":{"14":"3","2":"1","8":"2"}},{"id_classe_id":4,"id_recurso":2754,"id_subclasse_id":null,"nivel":null,"nome":"2º","reset":null,"slug":"2o","tipo":"table-only","valor":null,"valores_jso