    IF NOT EXISTS (
        SELECT 1 FROM home_tbruleset r
        WHERE r.checksum = 'da099956cb1abed5d158f64855076825d66e509a5d5aee0e4f19944291ce6289'
          AND r.manifest ->> 'class-catalog:4' = 'cdf29eb219368c9637d037e663f8b41ccac662b67aac776c8ce9efb217353be3'
