    ) THEN
        RAISE EXCEPTION 'Hunter ruleset PK/checksum collision';
    END IF;
    IF (
        SELECT count(*) FROM hunter_markdown_expected_r221 e,
             LATERAL jsonb_each_text(e.manifest) m(identity, checksum)
             JOIN home_tbcontentrevision r ON r.identity = m.identity AND r.checksum = m.checksum
    ) <> 21 THEN
        RAISE EXCEPTION 'Hunter ruleset dependency missing';
    END IF;
END;
$identity_check$;
INSERT INTO home_tbrulesetcontent (ruleset_id, revision_id, identity)
SELECT ruleset.id, revision.id, m.identity
FROM hunter_markdown_expected_r221 e,
     LATERAL jsonb_each_text(e.manifest) m(identity, checksum)
     JOIN home_tbcontentrevision revision
       ON revision.identity = m.identity AND revision.checksum = m.checksum
     CROSS JOIN home_tbruleset ruleset
WHERE ruleset.checksum = 'ed230c319a8959a78cce978a1e72d11281f9f03bbe49b4c3f0e0158eb2a6e0a2'
ON CONFLICT (ruleset_id, identity) DO NOTHING;
DO $verify$
BEGIN
    IF (
        SELECT count(*) FROM home_tbrulesetcontent entry
        JOIN home_tbruleset ruleset ON ruleset.id = entry.ruleset_id
        JOIN home_tbcontentrevision revision ON revision.id = entry.revision_id
        WHERE ruleset.checksum = 'ed230c319a8959a78cce978a1e72d11281f9f03bbe49b4c3f0e0158eb2a6e0a2'
          AND revision.identity = entry.identity
          AND revision.checksum = ruleset.manifest ->> entry.identity
    ) <> 21 OR (
        SELECT count(*) FROM home_tbrulesetcontent entry
        JOIN home_tbruleset ruleset ON ruleset.id = entry.ruleset_id
        WHERE ruleset.checksum = 'ed230c319a8959a78cce978a1e72d11281f9f03bbe49b4c3f0e0158eb2a6e0a2'
    ) <> 21 THEN
        RAISE EXCEPTION 'Hunter publication incomplete; transaction rolled back';
    END IF;
END;
$verify$;
COMMIT;
